    private static boolean isClonedStandalonePackage() {
        return sOriginalPackageName != null && !sOriginalPackageName.isEmpty() &&
                sStandalonePackageName != null && !sStandalonePackageName.isEmpty() &&
                !sOriginalPackageName.equals(sStandalonePackageName);
    }

    private static boolean isAccountIsolationActive() {
        return sIdentitySpoofEnabled || isClonedStandalonePackage();
    }

    private static boolean isYouTubeTarget() {
        return "com.google.android.youtube".equals(sOriginalPackageName) ||
                (sStandalonePackageName != null && (sStandalonePackageName.equals("com.google.android.youtube") ||
                        sStandalonePackageName.startsWith("com.google.android.youtube.")));
    }

    private static boolean isGoogleFirstPartyTarget() {
        return isYouTubeTarget() ||
                EmbeddedGmsCore.isGoogleFirstPartyPackage(sOriginalPackageName) ||
                EmbeddedGmsCore.isGoogleFirstPartyPackage(sStandalonePackageName);
    }

