    // YouTube Shell_HomeActivity -> WatchWhileActivity/MainActivity trampoline protection & Google-1P startup diagnostics
    private static volatile long sYouTubeMainActivityLaunchMs = 0L;
    private static volatile boolean sYouTubeNonShellActivityActive = false;
    private static volatile long sLastYouTubeRecoveryLaunchMs = 0L;
    private static final List<String> GOOGLE_1P_DIAG_EVENTS =
            Collections.synchronizedList(new ArrayList<String>());
    private static volatile String sLastGoogle1pErrorSummary = "";
    private static volatile boolean sGoogle1pErrorToastShown = false;

    private static boolean isYouTubeShellClassName(String clsName) {
        if (clsName == null || clsName.isEmpty()) return false;
        String lower = clsName.toLowerCase(Locale.US);
        return lower.contains("shell") || lower.contains("trampoline") || lower.contains("urlactivity");
    }

    private static boolean hasRecentYouTubeMainActivityLaunch() {
        if (sYouTubeNonShellActivityActive) return true;
        long lastMs = sYouTubeMainActivityLaunchMs;
        return lastMs > 0L && (SystemClock.elapsedRealtime() - lastMs) < 3500L;
    }

    private static void recordGoogle1pDiagEvent(String phase, Throwable t) {
        if (!isGoogleFirstPartyTarget()) return;
        try {
            StringBuilder sb = new StringBuilder();
            sb.append(phase != null ? phase : "err");
            if (t != null) {
                Throwable root = t;
                int depth = 0;
                while (root.getCause() != null && root.getCause() != root && depth++ < 4) {
                    root = root.getCause();
                }
                sb.append(": ").append(root.getClass().getSimpleName());
                String msg = root.getMessage();
                if (msg != null && !msg.isEmpty()) {
                    if (msg.length() > 140) msg = msg.substring(0, 140);
                    sb.append("(").append(msg).append(")");
                }
                StackTraceElement[] st = root.getStackTrace();
                if (st != null && st.length > 0 && st[0] != null) {
                    sb.append(" @ ").append(st[0].getClassName()).append(".").append(st[0].getMethodName())
                            .append(":").append(st[0].getLineNumber());
                }
            }
            final String line = sb.toString();
            if (sLastGoogle1pErrorSummary == null || sLastGoogle1pErrorSummary.isEmpty()) {
                sLastGoogle1pErrorSummary = line;
            }
            synchronized (GOOGLE_1P_DIAG_EVENTS) {
                if (GOOGLE_1P_DIAG_EVENTS.size() < 24) {
                    GOOGLE_1P_DIAG_EVENTS.add(line);
                }
            }
            final Context ctx = sAppContext;
            if (ctx != null) {
                Thread writer = new Thread(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            File dir = ctx.getFilesDir();
                            if (dir != null) {
                                File f = new File(dir, "yt_startup_diag.txt");
                                java.io.FileWriter fw = new java.io.FileWriter(f, true);
                                try {
                                    fw.write(System.currentTimeMillis() + " " + line + "\n");
                                    fw.flush();
                                } finally {
                                    try { fw.close(); } catch (Throwable ignored) {}
                                }
                            }
                        } catch (Throwable ignored) {}
                    }
                }, "Ghost1pDiag");
                writer.setDaemon(true);
                writer.start();
            }
        } catch (Throwable ignored) {}
    }

    private static void notifyGoogle1pStartupErrorIfNeeded(final Context ctx) {
        if (!isGoogleFirstPartyTarget() || sGoogle1pErrorToastShown) return;
        final String err = sLastGoogle1pErrorSummary;
        if (err == null || err.isEmpty() || ctx == null) return;
        sGoogle1pErrorToastShown = true;
        try {
            new Handler(Looper.getMainLooper()).post(new Runnable() {
                @Override
                public void run() {
                    try {
                        String shortMsg = err.length() > 180 ? err.substring(0, 180) : err;
                        Toast.makeText(ctx.getApplicationContext(), "[GhostDiag] " + shortMsg, Toast.LENGTH_LONG).show();
                    } catch (Throwable ignored) {}
                }
            });
        } catch (Throwable ignored) {}
    }

    private static boolean tryLaunchYouTubePrimaryMainActivity(Activity fromActivity) {
        if (!isYouTubeTarget() || fromActivity == null) return false;
        long now = SystemClock.elapsedRealtime();
        if (now - sLastYouTubeRecoveryLaunchMs < 2500L) return false;
        sLastYouTubeRecoveryLaunchMs = now;
        try {
            String pkg = (sStandalonePackageName != null && !sStandalonePackageName.isEmpty())
                    ? sStandalonePackageName
                    : fromActivity.getPackageName();
            if (pkg == null || pkg.isEmpty()) return false;

            String bestCls = null;
            int bestScore = -1;
            try {
                PackageInfo pi = fromActivity.getPackageManager().getPackageInfo(pkg, PackageManager.GET_ACTIVITIES);
                if (pi != null && pi.activities != null) {
                    for (int i = 0; i < pi.activities.length; i++) {
                        ActivityInfo ai = pi.activities[i];
                        if (ai == null || ai.name == null || ai.name.isEmpty()) continue;
                        String n = ai.name;
                        String nl = n.toLowerCase(Locale.US);
                        if (isYouTubeShellClassName(n) || nl.contains("settings") || nl.contains("license")
                                || nl.contains("missingsplits") || nl.contains("upload") || nl.contains("vr")
                                || nl.contains("livecreation") || nl.contains("shorts") || nl.contains("edit")) {
                            continue;
                        }
                        int score = -1;
                        if (n.equals("com.google.android.apps.youtube.app.watchwhile.MainActivity")) {
                            score = 100;
                        } else if (n.equals("com.google.android.apps.youtube.app.watchwhile.WatchWhileActivity")) {
                            score = 95;
                        } else if (nl.contains("watchwhile") && nl.endsWith("mainactivity")) {
                            score = 90;
                        } else if (nl.contains("watchwhile")) {
                            score = 80;
                        } else if (nl.endsWith(".mainactivity") && nl.contains("youtube")) {
                            score = 70;
                        }
                        if (score > bestScore) {
                            bestScore = score;
                            bestCls = n;
                        }
                    }
                }
            } catch (Throwable ignoredPm) {}

            if (bestCls == null || bestCls.isEmpty()) {
                bestCls = "com.google.android.apps.youtube.app.watchwhile.MainActivity";
            }

            Intent launchIntent = new Intent(Intent.ACTION_MAIN);
            launchIntent.addCategory(Intent.CATEGORY_LAUNCHER);
            launchIntent.setComponent(new ComponentName(pkg, bestCls));
            launchIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP);
            sYouTubeMainActivityLaunchMs = SystemClock.elapsedRealtime();
            fromActivity.startActivity(launchIntent);
            notifyGoogle1pStartupErrorIfNeeded(fromActivity);
            return true;
        } catch (Throwable t) {
            recordGoogle1pDiagEvent("ytRecover", t);
            notifyGoogle1pStartupErrorIfNeeded(fromActivity);
            return false;
        }
    }

