    private static String normalizeLangCode(String code) {
        if (code == null) return "en";
        String c = code.trim().toLowerCase(Locale.US);
        if ("bn".equals(c) || c.startsWith("bn")) return "bn";
        if ("hi".equals(c) || c.startsWith("hi")) return "hi";
        return "en";
    }

    private static String tr(String en, String bn, String hi) {
        String lang = sAppLanguage;
        if ("bn".equalsIgnoreCase(lang)) return bn;
        if ("hi".equalsIgnoreCase(lang)) return hi;
        return en;
    }

    private static volatile long sLastHostFileLangCheckRealMs = 0L;
    private static volatile String sCachedHostFileLang = "";

    private static String readHostGhostDeviceLanguageFromFiles(long minModifiedAfterMs) {
        long nowEl = SystemClock.elapsedRealtime();
        if (sLastHostFileLangCheckRealMs > 0L && (nowEl - sLastHostFileLangCheckRealMs) < 8000L) {
            return sCachedHostFileLang;
        }
        sLastHostFileLangCheckRealMs = nowEl;
        String[] langPaths = new String[]{
                "/sdcard/Download/PhantomStandaloneAPKs/.phantom_live_language.txt",
                "/storage/emulated/0/Download/PhantomStandaloneAPKs/.phantom_live_language.txt",
                "/sdcard/Download/.phantom_live_language.txt",
                "/data/local/tmp/.phantom_live_language.txt"
        };
        for (int i = 0; i < langPaths.length; i++) {
            File f = new File(langPaths[i]);
            try {
                if (f.exists() && f.isFile() && f.length() > 0L && f.length() < 32L) {
                    if (minModifiedAfterMs > 0L && f.lastModified() > 0L && f.lastModified() < minModifiedAfterMs) {
                        continue;
                    }
                    BufferedReader br = new BufferedReader(new FileReader(f));
                    String line = br.readLine();
                    br.close();
                    if (line != null && !line.trim().isEmpty()) {
                        sCachedHostFileLang = normalizeLangCode(line.trim());
                        return sCachedHostFileLang;
                    }
                }
            } catch (Throwable ignored) {}
        }
        sCachedHostFileLang = "";
        return "";
    }

