    /**
     * Unlocks Android 9–15 (API 28+) ART Hidden API restrictions via meta-reflection on VMRuntime
     * so internal fields on LocationManager, SystemSensorManager, ServiceManager, LoadedApk,
     * and Parcel are 100% accessible inside built standalone APKs.
     */
    private static void bypassHiddenApiRestrictions() {
        try {
            sMetaGetDeclaredField = Class.class.getDeclaredMethod("getDeclaredField", String.class);
            sMetaGetDeclaredField.setAccessible(true);
            sMetaGetDeclaredFields = Class.class.getDeclaredMethod("getDeclaredFields");
            sMetaGetDeclaredFields.setAccessible(true);
            sMetaGetDeclaredMethod = Class.class.getDeclaredMethod("getDeclaredMethod", String.class, Class[].class);
            sMetaGetDeclaredMethod.setAccessible(true);
        } catch (Throwable ignored) {}
        if (Build.VERSION.SDK_INT < 28) return;
        try {
            Method forName = Class.class.getDeclaredMethod("forName", String.class);
            forName.setAccessible(true);
            Method getDeclaredMethod = sMetaGetDeclaredMethod != null
                    ? sMetaGetDeclaredMethod
                    : Class.class.getDeclaredMethod("getDeclaredMethod", String.class, Class[].class);
            getDeclaredMethod.setAccessible(true);
            Class<?> vmRuntimeClass = (Class<?>) forName.invoke(null, "dalvik.system.VMRuntime");
            Method getRuntime = (Method) getDeclaredMethod.invoke(vmRuntimeClass, "getRuntime", new Class[0]);
            getRuntime.setAccessible(true);
            Method setHiddenApiExemptions = (Method) getDeclaredMethod.invoke(
                    vmRuntimeClass, "setHiddenApiExemptions", new Class[]{String[].class});
            setHiddenApiExemptions.setAccessible(true);
            Object vmRuntime = getRuntime.invoke(null);
            setHiddenApiExemptions.invoke(vmRuntime, new Object[]{new String[]{"L"}});
        } catch (Throwable ignored) {}
    }

