    /**
     * Called by {@link android.os.Procest} before {@code Process.killProcess} or {@code Process.sendSignal}.
     * Blocks self-termination when a non-fatal background exception or attestation check attempts to kill the app.
     */
    public static boolean shouldInterceptProcessKill(int pid, int sig) {
        try {
            if (sIsClearingInProgress) {
                return false;
            }
            int myPid = android.os.Process.myPid();
            if (pid != myPid && pid > 0) {
                return false;
            }
            if (sig != 9 && sig != 3 && sig != 6 && sig != 11 && sig != 15) {
                return false;
            }
            resetRuntimeInitCrashingFlag();
            boolean fromUncaughtOrExit = false;
            StackTraceElement[] stack = Thread.currentThread().getStackTrace();
            if (stack != null) {
                for (StackTraceElement el : stack) {
                    String mn = el.getMethodName();
                    String cn = el.getClassName();
                    if ("uncaughtException".equals(mn)
                            || "dispatchUncaughtException".equals(mn)
                            || (cn != null && (cn.contains("RuntimeInit")
                                || cn.contains("Crash")
                                || cn.contains("Primes")
                                || cn.contains("Uncaught")))) {
                        fromUncaughtOrExit = true;
                        break;
                    }
                }
            }
            if (!isGoogleFirstPartyTarget() && !fromUncaughtOrExit) {
                return false;
            }
            Looper mainLooper = Looper.getMainLooper();
            boolean isMain = mainLooper != null && Thread.currentThread() == mainLooper.getThread();
            if (isMain && fromUncaughtOrExit) {
                recoverMainThreadUiStateAfterException();
                while (true) {
                    try {
                        Looper.loop();
                    } catch (Throwable t) {
                        resetRuntimeInitCrashingFlag();
                        recoverMainThreadUiStateAfterException();
                    }
                }
            } else if (!isMain && fromUncaughtOrExit) {
                while (!sIsClearingInProgress) {
                    try {
                        Thread.sleep(Long.MAX_VALUE);
                    } catch (Throwable ignored) {}
                }
            }
            return true;
        } catch (Throwable ignored) {
            return isGoogleFirstPartyTarget() && !sIsClearingInProgress;
        }
    }

    private static void resetRuntimeInitCrashingFlag() {
        try {
            Class<?> riClass = Class.forName("com.android.internal.os.RuntimeInit");
            Field mCrashingField = riClass.getDeclaredField("mCrashing");
            mCrashingField.setAccessible(true);
            mCrashingField.setBoolean(null, false);
        } catch (Throwable ignored) {}
    }

    private static boolean isCalledFromExternalUncaughtHandler() {
        try {
            StackTraceElement[] stack = Thread.currentThread().getStackTrace();
            if (stack == null) return false;
            int uncaughtCount = 0;
            for (StackTraceElement el : stack) {
                String cn = el.getClassName();
                String mn = el.getMethodName();
                if ("uncaughtException".equals(mn)) {
                    if (cn != null && !cn.startsWith("com.example.standalone.") && !cn.startsWith("java.lang.Thread")) {
                        return true;
                    }
                    uncaughtCount++;
                }
            }
            return uncaughtCount > 1;
        } catch (Throwable ignored) {
            return false;
        }
    }

    private static void installYouTubeShutdownHookShieldIfNeeded() {
        if (sYouTubeShutdownHookInstalled || !isGoogleFirstPartyTarget()) return;
        sYouTubeShutdownHookInstalled = true;
        try {
            Runtime.getRuntime().addShutdownHook(new Thread("GhostShutdownShield") {
                @Override
                public void run() {
                    if (sIsClearingInProgress) return;
                    resetRuntimeInitCrashingFlag();
                    while (!sIsClearingInProgress) {
                        try {
                            Thread.sleep(Long.MAX_VALUE);
                        } catch (Throwable ignored) {}
                    }
                }
            });
        } catch (Throwable ignored) {}
    }

    private static void ensureCrashShieldInstalled() {
        try {
            resetRuntimeInitCrashingFlag();
            installYouTubeShutdownHookShieldIfNeeded();
            if (sCrashShieldHandlerInstance == null) {
                sCrashShieldHandlerInstance = new Thread.UncaughtExceptionHandler() {
                    @Override
                    public void uncaughtException(Thread t, Throwable e) {
                        resetRuntimeInitCrashingFlag();
                        if (isGoogleFirstPartyTarget()) {
                            recordGoogle1pDiagEvent("uncaught(" + (t != null ? t.getName() : "?") + ")", e);
                        }
                        try {
                            if (e instanceof OutOfMemoryError) {
                                try {
                                    SCANNED_STATIC_CLASSES.clear();
                                    System.gc();
                                } catch (Throwable ignoredOom) {}
                            }
                            Looper mainLooper = Looper.getMainLooper();
                            boolean isMainThread = (mainLooper != null && t == mainLooper.getThread());
                            if (!isMainThread) {
                                // CRITICAL: If an external UncaughtExceptionHandler wrapper (e.g. YouTube Primes /
                                // GoogleCrashReporter / RxJava / RuntimeInit$KillApplicationHandler) invoked us as its
                                // previousHandler inside a try { ... } finally { Process.killProcess(myPid()); System.exit(10); },
                                // returning here will immediately execute the wrapper's finally block and kill the app!
                                // Parking the dying background thread prevents the wrapper's finally block from ever running.
                                if (isGoogleFirstPartyTarget() || isCalledFromExternalUncaughtHandler()) {
                                    while (!sIsClearingInProgress) {
                                        try {
                                            Thread.sleep(Long.MAX_VALUE);
                                        } catch (Throwable ignored) {}
                                    }
                                }
                                return;
                            }
                            // On the Main UI Thread: keep Looper.loop() alive so the app never closes ("কেটে যায় না"),
                            // while unsticking any interrupted ViewRootImpl traversal/sync barrier or Choreographer frame!
                            recoverMainThreadUiStateAfterException();
                            int oomCount = 0;
                            int rapidFailCount = 0;
                            long lastLoopThrowMs = SystemClock.elapsedRealtime();
                            while (true) {
                                try {
                                    Looper.loop();
                                    return;
                                } catch (Throwable loopEx) {
                                    resetRuntimeInitCrashingFlag();
                                    long nowMs = SystemClock.elapsedRealtime();
                                    if (nowMs - lastLoopThrowMs < 40L) {
                                        rapidFailCount++;
                                    } else {
                                        rapidFailCount = 0;
                                    }
                                    lastLoopThrowMs = nowMs;

                                    if (loopEx instanceof OutOfMemoryError) {
                                        try {
                                            SCANNED_STATIC_CLASSES.clear();
                                            System.gc();
                                        } catch (Throwable ignoredGc) {}
                                        if (++oomCount > 5) {
                                            try { Thread.sleep(200L); } catch (Throwable ignoredSlp) {}
                                            oomCount = 0;
                                        }
                                    }
                                    recoverMainThreadUiStateAfterException();
                                    if (rapidFailCount >= 4) {
                                        try {
                                            Thread.sleep(Math.min(250L, 16L * rapidFailCount));
                                        } catch (Throwable ignoredSlp) {}
                                        if (rapidFailCount > 20) {
                                            rapidFailCount = 4;
                                        }
                                    }
                                }
                            }
                        } catch (Throwable ignored) {}
                        // Never delegate to RuntimeInit$KillApplicationHandler (sFallbackUncaughtHandler)
                        // so Android never shows "<App> keeps stopping" or kills the built APK!
                    }
                };
            }
            if (sCrashShieldPreHandlerInstance == null) {
                sCrashShieldPreHandlerInstance = new Thread.UncaughtExceptionHandler() {
                    @Override
                    public void uncaughtException(Thread t, Throwable e) {
                        resetRuntimeInitCrashingFlag();
                        try {
                            // Android's Thread.dispatchUncaughtException invokes uncaughtExceptionPreHandler
                            // BEFORE evaluating getUncaughtExceptionHandler(). Even if YouTube / Breakpad / Firebase
                            // overwrote defaultUncaughtExceptionHandler or t.uncaughtExceptionHandler, restoring
                            // sCrashShieldHandlerInstance here guarantees our CrashShield handles the exception
                            // instead of RuntimeInit$KillApplicationHandler!
                            if (sCrashShieldHandlerInstance != null) {
                                Thread.setDefaultUncaughtExceptionHandler(sCrashShieldHandlerInstance);
                                if (t != null) {
                                    t.setUncaughtExceptionHandler(sCrashShieldHandlerInstance);
                                }
                            }
                        } catch (Throwable ignoredPre) {}
                    }
                };
            }
            try {
                Method setPre = Thread.class.getDeclaredMethod("setUncaughtExceptionPreHandler", Thread.UncaughtExceptionHandler.class);
                setPre.setAccessible(true);
                setPre.invoke(null, sCrashShieldPreHandlerInstance);
            } catch (Throwable ignoredPreInstall) {
                try {
                    Field preField = Thread.class.getDeclaredField("uncaughtExceptionPreHandler");
                    preField.setAccessible(true);
                    preField.set(null, sCrashShieldPreHandlerInstance);
                } catch (Throwable ignored2) {}
            }
            Thread.UncaughtExceptionHandler current = Thread.getDefaultUncaughtExceptionHandler();
            if (current != sCrashShieldHandlerInstance) {
                if (current != null) {
                    sFallbackUncaughtHandler = current;
                }
                Thread.setDefaultUncaughtExceptionHandler(sCrashShieldHandlerInstance);
                CRASH_SHIELD_INSTALLED.set(true);
            }
            Thread curThread = Thread.currentThread();
            if (curThread != null && curThread.getUncaughtExceptionHandler() != sCrashShieldHandlerInstance) {
                curThread.setUncaughtExceptionHandler(sCrashShieldHandlerInstance);
            }
            Looper mainLooper = Looper.getMainLooper();
            if (mainLooper != null) {
                Thread mainThread = mainLooper.getThread();
                if (mainThread != null && mainThread.getUncaughtExceptionHandler() != sCrashShieldHandlerInstance) {
                    mainThread.setUncaughtExceptionHandler(sCrashShieldHandlerInstance);
                }
            }
            try {
                Class<?> riClass = Class.forName("com.android.internal.os.RuntimeInit");
                for (Field f : riClass.getDeclaredFields()) {
                    if (Thread.UncaughtExceptionHandler.class.isAssignableFrom(f.getType())) {
                        f.setAccessible(true);
                        f.set(null, sCrashShieldHandlerInstance);
                    }
                }
            } catch (Throwable ignored) {}
            // Thread.setUncaughtExceptionPreHandler + defaultUncaughtExceptionHandler + mainThread + currentThread
            // already intercept every thread in O(1) without stalling the Main Thread via ThreadGroup.enumerate()!
        } catch (Throwable ignored) {}
    }

    /**
     * Unsticks Choreographer and all active ViewRootImpl instances if an exception unwound out of
     * performTraversals() / doFrame() while a Sync Barrier (mTraversalBarrier) or mInLayout was set.
     * Never force-finishes or replaces the user's current Activity.
     */
    private static void recoverMainThreadUiStateAfterException() {
        try {
            // 1. Reset Choreographer frame-scheduled flags if stuck
            try {
                Choreographer ch = Choreographer.getInstance();
                if (ch != null) {
                    Field fSched = findFieldRecursive(ch.getClass(), "mFrameScheduled");
                    if (fSched != null) {
                        fSched.setAccessible(true);
                        fSched.setBoolean(ch, false);
                    }
                    Field fRun = findFieldRecursive(ch.getClass(), "mCallbacksRunning");
                    if (fRun != null) {
                        fRun.setAccessible(true);
                        fRun.setBoolean(ch, false);
                    }
                }
            } catch (Throwable ignoredCh) {}

            // 2. Remove any stuck Sync Barrier (mTraversalBarrier) from Main Looper MessageQueue
            // and reset mTraversalScheduled / mInLayout on all ViewRootImpls in WindowManagerGlobal
            MessageQueue mq = Looper.getMainLooper().getQueue();
            Method removeSyncBarrier = null;
            if (mq != null) {
                try {
                    removeSyncBarrier = MessageQueue.class.getDeclaredMethod("removeSyncBarrier", int.class);
                    removeSyncBarrier.setAccessible(true);
                } catch (Throwable ignoredMethod) {}
            }
            Class<?> wmgClass = Class.forName("android.view.WindowManagerGlobal");
            Method getInstance = wmgClass.getDeclaredMethod("getInstance");
            getInstance.setAccessible(true);
            Object wmg = getInstance.invoke(null);
            if (wmg != null) {
                Field rootsField = findFieldRecursive(wmgClass, "mRoots");
                if (rootsField != null) {
                    rootsField.setAccessible(true);
                    Object rootsObj = rootsField.get(wmg);
                    if (rootsObj instanceof List) {
                        List<?> roots = (List<?>) rootsObj;
                        for (int i = 0; i < roots.size(); i++) {
                            Object root = roots.get(i);
                            if (root == null) continue;
                            try {
                                Field fBarrier = findFieldRecursive(root.getClass(), "mTraversalBarrier");
                                if (fBarrier != null) {
                                    fBarrier.setAccessible(true);
                                    int token = fBarrier.getInt(root);
                                    if (token > 0 && removeSyncBarrier != null && mq != null) {
                                        try {
                                            removeSyncBarrier.invoke(mq, Integer.valueOf(token));
                                        } catch (Throwable ignoredBarrier) {}
                                    }
                                    fBarrier.setInt(root, -1);
                                }
                            } catch (Throwable ignoredB) {}
                            try {
                                Field fTrav = findFieldRecursive(root.getClass(), "mTraversalScheduled");
                                if (fTrav != null) {
                                    fTrav.setAccessible(true);
                                    fTrav.setBoolean(root, false);
                                }
                            } catch (Throwable ignoredT) {}
                            try {
                                Field fInLayout = findFieldRecursive(root.getClass(), "mInLayout");
                                if (fInLayout != null) {
                                    fInLayout.setAccessible(true);
                                    fInLayout.setBoolean(root, false);
                                }
                            } catch (Throwable ignoredL) {}
                            try {
                                Field fHandling = findFieldRecursive(root.getClass(), "mHandlingLayoutInLayoutRequest");
                                if (fHandling != null) {
                                    fHandling.setAccessible(true);
                                    fHandling.setBoolean(root, false);
                                }
                            } catch (Throwable ignoredH) {}
                            try {
                                Method sched = findMethodRecursive(root.getClass(), "scheduleTraversals");
                                if (sched != null && sched.getParameterTypes().length == 0) {
                                    sched.setAccessible(true);
                                    sched.invoke(root);
                                }
                            } catch (Throwable ignoredS) {}
                        }
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    private static final AtomicBoolean EARLY_BOOTSTRAPPED = new AtomicBoolean(false);

    private static volatile boolean sEarlyBootstrappedFast = false;

    public static void ensureEarlyBootstrappedFast() {
        if (sEarlyBootstrappedFast) return;
        ensureEarlyBootstrapped();
    }

    /**
     * Ensures device identity spoofing and host isolation are bootstrapped as early as possible,
     * even if a target app class or AppComponentFactory queries SystemProperties, Build, or MediaDrm
     * before StandaloneBootstrapProvider.attachInfo() is called.
     */
    public static void ensureEarlyBootstrapped() {
        if (!EARLY_BOOTSTRAPPED.compareAndSet(false, true)) {
            sEarlyBootstrappedFast = true;
            return;
        }
        sEarlyBootstrappedFast = true;
        bypassHiddenApiRestrictions();
        ensureCrashShieldInstalled();
        InputStream in = null;
        try {
            byte[] cfgBytes = readEmbeddedConfigBytes(null);
            if (cfgBytes != null && cfgBytes.length > 0) {
                JSONObject json = new JSONObject(new String(cfgBytes, StandardCharsets.UTF_8));
                sOriginalPackageName = json.optString("originalPackageName", sOriginalPackageName);
                sStandalonePackageName = json.optString("standalonePackageName", sStandalonePackageName);
                sOriginalSignatureHex = json.optString("originalSignatureHex", sOriginalSignatureHex);
                String origAcf = json.optString("originalAppComponentFactory", "");
                if (origAcf != null && !origAcf.isEmpty()) {
                    sOriginalAppComponentFactoryName = origAcf;
                }
                sHostInstanceId = json.optString("hostInstanceId", sHostInstanceId);
                sBakedSpeedEnabled = json.optBoolean("speedEnabled", false);
                sBakedStepWalkEnabled = json.optBoolean("stepWalkEnabled", false);
                sBakedRootBypassEnabled = json.optBoolean("rootBypassEnabled", false);
                sBakedIdentitySpoofEnabled = true;
                sBakedAdBypassEnabled = json.optBoolean("adBypassEnabled", false);
                sSpeedFeatureEnabled = sBakedSpeedEnabled;
                sStepWalkFeatureEnabled = sBakedStepWalkEnabled;
                sRootBypassFeatureEnabled = sBakedRootBypassEnabled;
                sIdentitySpoofEnabled = true;
                sAdBypassFeatureEnabled = sBakedAdBypassEnabled;
                long earlyBuiltTs = json.optLong("builtTimestamp", 0L);
                if (earlyBuiltTs > 0L) {
                    sBuiltTimestampMs = earlyBuiltTs;
                }
                String earlyLang = json.optString("appLanguage", "");
                if (earlyLang != null && !earlyLang.trim().isEmpty()) {
                    sAppLanguage = normalizeLangCode(earlyLang);
                }
                String liveFileLang = readHostGhostDeviceLanguageFromFiles(sBuiltTimestampMs);
                if (liveFileLang != null && !liveFileLang.isEmpty()) {
                    sAppLanguage = liveFileLang;
                }
                applyBuildFieldsFromJson(json);
            }
            if (sIdentitySpoofEnabled) {
                long vaultClearTs = 0L;
                boolean loadedVault = false;
                String earlyVaultJson = readPermanentIdentityJsonFromFiles(sStandalonePackageName);
                if (earlyVaultJson != null && !earlyVaultJson.isEmpty()) {
                    try {
                        JSONObject vaultObj = new JSONObject(earlyVaultJson);
                        String vm = vaultObj.optString("deviceModel", "");
                        String vfp = vaultObj.optString("buildFingerprint", "");
                        vaultClearTs = Math.max(vaultObj.optLong("userClearTsMs", 0L), vaultObj.optLong("apkBuiltTsMs", 0L));
                        if (vaultClearTs > sUserClearTimestampMs) {
                            sUserClearTimestampMs = vaultClearTs;
                        }
                        if (!vm.isEmpty() && !isMatchingRealHostHardware(vm, vfp)) {
                            applyRuntimeIdentityFromJson(vaultObj);
                            loadedVault = true;
                        }
                    } catch (Throwable ignoredVault) {}
                }
                boolean isMultiInstallVariant = sStandalonePackageName != null && sStandalonePackageName.contains(".id");
                String hostLiveJson = readHostGhostDeviceIdentityFromFiles();
                if (!isMultiInstallVariant && hostLiveJson != null && !hostLiveJson.isEmpty()) {
                    try {
                        JSONObject hostObj = new JSONObject(hostLiveJson);
                        long hostResetTs = hostObj.optLong("resetTimestamp", 0L);
                        String hm = hostObj.optString("deviceModel", "");
                        String hfp = hostObj.optString("buildFingerprint", "");
                        long minRequiredTs = Math.max(sBuiltTimestampMs, Math.max(sUserClearTimestampMs, vaultClearTs));
                        if (!hm.isEmpty() && !isMatchingRealHostHardware(hm, hfp) &&
                                (!loadedVault || (hostResetTs > 0L && hostResetTs > minRequiredTs))) {
                            applyBuildFieldsFromJson(hostObj);
                        }
                    } catch (Throwable ignoredHost) {}
                }
                if (isMatchingRealHostHardware(sDeviceModel, sBuildFingerprint)) {
                    generateFreshRandomIdentityInMemory();
                }
            }
        } catch (Throwable ignored) {
        } finally {
            if (in != null) {
                try { in.close(); } catch (Throwable ignored) {}
            }
        }
        try {
            installEarlyAccountAndCredentialIsolation();
            installActivityTaskManagerAntiExitProxy();
            installPackageManagerSignatureProxy(null);
            installActivityThreadInstrumentationHook();
            installWebViewFactoryAndBuildInfoHook();
            if (isYouTubeTarget()) {
                sAdBypassFeatureEnabled = true;
            }
        } catch (Throwable ignoredEarlyHooks) {}
    }

    private static String readHostGhostDeviceIdentityFromFiles() {
        long nowEl = SystemClock.elapsedRealtime();
        if (sLastHostFileIdCheckRealMs > 0L && (nowEl - sLastHostFileIdCheckRealMs) < 3000L) {
            return sCachedHostFileIdJson;
        }
        sLastHostFileIdCheckRealMs = nowEl;
        String[] hostPaths = new String[]{
                "/sdcard/Download/phantom_identity.json",
                "/storage/emulated/0/Download/phantom_identity.json",
                "/sdcard/phantom_identity.json",
                "/data/local/tmp/phantom_identity.json"
        };
        for (int i = 0; i < hostPaths.length; i++) {
            File f = new File(hostPaths[i]);
            if (f.exists() && f.isFile() && f.length() > 32L) {
                BufferedReader br = null;
                try {
                    br = new BufferedReader(new FileReader(f));
                    StringBuilder sb = new StringBuilder();
                    String line;
                    while ((line = br.readLine()) != null) {
                        sb.append(line);
                    }
                    String content = sb.toString().trim();
                    if (content.startsWith("{") && content.contains("deviceModel")) {
                        sCachedHostFileIdJson = content;
                        return content;
                    }
                } catch (Throwable ignored) {
                } finally {
                    if (br != null) {
                        try { br.close(); } catch (Throwable ignored) {}
                    }
                }
            }
        }
        sCachedHostFileIdJson = "";
        return "";
    }

    public static byte[] getVirtualWidevineIdBytes() {
        ensureEarlyBootstrapped();
        if (!sIdentitySpoofEnabled) {
            return null;
        }
        String hex = sWidevineDrmId;
        if (hex == null || hex.length() < 32) {
            hex = "c6a43e129d3f5f7c9e5b32415a6978cd9012ef3456789abc0123456789abcdef";
        }
        int len = Math.min(64, (hex.length() / 2) * 2);
        byte[] out = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            int hi = Character.digit(hex.charAt(i), 16);
            int lo = Character.digit(hex.charAt(i + 1), 16);
            if (hi < 0) hi = 0;
            if (lo < 0) lo = 0;
            out[i / 2] = (byte) ((hi << 4) | lo);
        }
        return out;
    }

    public static String getSpoofedMediaDrmPropertyString(String propertyName) {
        ensureEarlyBootstrapped();
        if (!sIdentitySpoofEnabled || propertyName == null) return null;
        String lower = propertyName.toLowerCase(Locale.US);
        if ("vendor".equals(lower)) return "Google";
        if ("version".equals(lower)) return "16.1.0";
        if ("description".equals(lower)) return "Widevine CDM";
        if ("algorithms".equals(lower)) return "AES/CBC/NoPadding,HmacSHA256";
        if ("securitylevel".equals(lower)) return "L1";
        if ("systemid".equals(lower)) {
            int sysId = 4000 + (Math.abs((sWidevineDrmId != null ? sWidevineDrmId : "phantom").hashCode()) % 20000);
            return String.valueOf(sysId);
        }
        return null;
    }

