    private static boolean isInfrastructureBackgroundThread() {
        if (Looper.myLooper() == Looper.getMainLooper()) {
            return false;
        }
        try {
            return isInfrastructureThreadName(Thread.currentThread().getName());
        } catch (Throwable ignored) {
            return false;
        }
    }

    public static boolean isSpeedScaled() {
        return sSpeedFeatureEnabled && Math.abs(sSpeedMultiplier - 1.0f) > 0.01f;
    }

    public static boolean isClockVirtualized() {
        return sSpeedFeatureEnabled && (sClockScaledEver || Math.abs(sSpeedMultiplier - 1.0f) > 0.01f);
    }

    public static long getVirtualUptimeNanos() {
        if (!isClockVirtualized()) {
            if (Build.VERSION.SDK_INT >= 36) {
                try {
                    return SystemClock.uptimeNanos();
                } catch (Throwable ignored) {}
            }
            return SystemClock.uptimeMillis() * 1_000_000L;
        }
        return (long) (getVirtualUptimeMillis() * 1_000_000.0);
    }

    public static long getVirtualWallTimeMillis() {
        if (!isClockVirtualized() || isInfrastructureBackgroundThread()) {
            return System.currentTimeMillis();
        }
        long nowWall = System.currentTimeMillis();
        sLastClockReadRealMs = SystemClock.elapsedRealtime();
        LockFreeClockState st = sLockFreeClock;
        long dWall = Math.max(0L, nowWall - st.realWallAnchor);
        long res = Math.max(1L, (long) (st.virWallBase + (double) dWall * (double) st.mult));
        long prev = sLastReturnedWall;
        if (res < prev) return prev;
        sLastReturnedWall = res;
        return res;
    }

