    public static void registerTrackableAnimation(Animation anim) {
        if (anim == null) return;
        try {
            if (!TRACKED_ANIMATIONS.containsKey(anim)) {
                TRACKED_ANIMATIONS.put(anim, new long[]{SystemClock.elapsedRealtime()});
            }
        } catch (Throwable ignored) {}
    }

    public static void sleepScaled(long ms) {
        if (ms <= 0L) return;
        // On the Main UI Thread: yield and sleep briefly (up to 4ms) so spin-wait loops waiting on
        // background login/DB/Litho threads do not starve CPU/locks while still preventing ANRs!
        if (Looper.myLooper() == Looper.getMainLooper()) {
            try {
                Thread.yield();
                SystemClock.sleep(Math.min(ms, 4L));
            } catch (Throwable ignored) {}
            return;
        }

        if (!isSpeedScaled() || isInfrastructureBackgroundThread()) {
            try {
                SystemClock.sleep(ms);
            } catch (Throwable ignored) {}
            return;
        }

        float mult = sSpeedMultiplier;
        long waitMs = Math.max(1L, Math.round((double) ms / (double) mult));
        try {
            Thread.sleep(waitMs);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void setSpeedMultiplier(float newMult) {
        if (!sSpeedFeatureEnabled) {
            newMult = 1.0f;
        }
        final float clamped = Math.max(0.001f, Math.min(1000.0f, newMult));
        if (Math.abs(clamped - sSpeedMultiplier) < 0.0005f) {
            return;
        }
        synchronized (CLOCK_LOCK) {
            if (!sClockScaledEver) {
                sRealWallAnchor = System.currentTimeMillis();
                sVirtualWallBase = (double) sRealWallAnchor;
                sRealNanoAnchor = System.nanoTime();
                sVirtualNanoBase = (double) sRealNanoAnchor;
                sRealElapsedAnchor = SystemClock.elapsedRealtime();
                sVirtualElapsedBase = (double) sRealElapsedAnchor;
                sRealElapsedNanosAnchor = SystemClock.elapsedRealtimeNanos();
                sVirtualElapsedNanosBase = (double) sRealElapsedNanosAnchor;
                sRealUptimeAnchor = SystemClock.uptimeMillis();
                sVirtualUptimeBase = (double) sRealUptimeAnchor;
                sLastReturnedWall = sRealWallAnchor;
                sLastReturnedNano = sRealNanoAnchor;
                sLastReturnedElapsed = sRealElapsedAnchor;
                sLastReturnedElapsedNanos = sRealElapsedNanosAnchor;
                sLastReturnedUptime = sRealUptimeAnchor;
                if (Math.abs(clamped - 1.0f) > 0.01f) {
                    sClockScaledEver = true;
                }
            } else {
                // Keep sClockScaledEver = true and advance from current virtual bases even when clamped == 1.0f
                // (matching XposedEntry.kt) so virtual clocks never jump backwards or freeze on sLastReturned*!
                advanceAllClocksLocked(sSpeedMultiplier);
                sLastReturnedWall = Math.max(sLastReturnedWall, (long) sVirtualWallBase);
                sLastReturnedNano = Math.max(sLastReturnedNano, (long) sVirtualNanoBase);
                sLastReturnedElapsed = Math.max(sLastReturnedElapsed, (long) sVirtualElapsedBase);
                sLastReturnedElapsedNanos = Math.max(sLastReturnedElapsedNanos, (long) sVirtualElapsedNanosBase);
                sLastReturnedUptime = Math.max(sLastReturnedUptime, (long) sVirtualUptimeBase);
            }
            sSpeedMultiplier = clamped;
            sLockFreeClock = new LockFreeClockState(
                    clamped,
                    sRealWallAnchor, sVirtualWallBase,
                    sRealNanoAnchor, sVirtualNanoBase,
                    sRealElapsedAnchor, sVirtualElapsedBase,
                    sRealElapsedNanosAnchor, sVirtualElapsedNanosBase,
                    sRealUptimeAnchor, sVirtualUptimeBase
            );
        }

        applyValueAnimatorScale(clamped, true);
        if (sClockScaledEver || Math.abs(clamped - 1.0f) > 0.01f) {
            scheduleMasterChoreographerHookIfNeeded();
            if (Looper.myLooper() == Looper.getMainLooper()) {
                accelerateMainLooperAppRunnables(clamped, 0L);
            } else {
                Handler h = sEngineMainHandler != null ? sEngineMainHandler : new Handler(Looper.getMainLooper());
                final float targetMult = clamped;
                h.postAtFrontOfQueue(new Runnable() {
                    @Override
                    public void run() {
                        accelerateMainLooperAppRunnables(targetMult, 0L);
                    }
                });
                accelerateMainLooperAppRunnables(clamped, 0L);
            }
            accelerateJavaUtilTimers(clamped, 0L);
        }
        sLastWebViewInjectRealMs = 0L;
        sLastChronoAnimShiftRealMs = 0L;
        if (Looper.myLooper() == Looper.getMainLooper()) {
            updateTrackedViewsSpeed(clamped);
            refreshAllHudViews();
        } else {
            Handler h = sEngineMainHandler != null ? sEngineMainHandler : new Handler(Looper.getMainLooper());
            final float targetMult = clamped;
            h.post(new Runnable() {
                @Override
                public void run() {
                    updateTrackedViewsSpeed(targetMult);
                    refreshAllHudViews();
                }
            });
        }
    }

