        sBluetoothAddress = prefs.getString("runtime_bt_address", sBluetoothAddress);
        sBluetoothName = prefs.getString("runtime_bt_name", sBluetoothName);
        sUserAgent = prefs.getString("runtime_user_agent", sUserAgent);
        sWebviewHash = prefs.getString("runtime_webview_hash", sWebviewHash);
        sTimezone = prefs.getString("runtime_timezone", sTimezone);
        sLocaleTag = prefs.getString("runtime_locale_tag", sLocaleTag);
        sRegionCode = prefs.getString("runtime_region_code", sRegionCode);
        sVirtualInstallTimeMs = prefs.getLong("runtime_install_time", sVirtualInstallTimeMs);

        populateCpuProfileForHardware(sSocHardware, sBoard, sGpuVendor, sGpuRenderer, Math.abs(sAndroidId.hashCode()));
        sSocManufacturer = prefs.getString("runtime_soc_manufacturer", sSocManufacturer);
        sSocModelCode = prefs.getString("runtime_soc_model_code", sSocModelCode);
        sCpuProcessorName = prefs.getString("runtime_cpu_processor", sCpuProcessorName);
        sCpuTopCardSummary = prefs.getString("runtime_cpu_top_summary", sCpuTopCardSummary);
        sCpuArchClusterSummary = prefs.getString("runtime_cpu_arch_clusters", sCpuArchClusterSummary);
