    private static void populateCpuProfileForHardware(String hardware, String board, String gpuVendor, String gpuRenderer, int seedVal) {
        int chosenIdx = Math.abs(seedVal) % SOC_CPU_PROFILES.length;
        String hwLower = hardware != null ? hardware.toLowerCase(Locale.US) : "";
        String brdLower = board != null ? board.toLowerCase(Locale.US) : "";
        for (int i = 0; i < SOC_CPU_PROFILES.length; i++) {
            String[] p = SOC_CPU_PROFILES[i];
            if (p[8].equalsIgnoreCase(hwLower) && p[9].equalsIgnoreCase(brdLower)) {
                chosenIdx = i;
                break;
            }
        }
        String[] soc = SOC_CPU_PROFILES[chosenIdx];
        sSocManufacturer = soc[0];
        sSocModelCode = soc[1];
        sCpuProcessorName = soc[2] + " (" + soc[1] + ")";
        sCpuTopCardSummary = soc[2] + " (" + soc[1] + ")\n" + soc[3] + " • " + soc[7] + " Cores • " + (gpuRenderer != null && !gpuRenderer.isEmpty() ? gpuRenderer : soc[11]);
        sCpuArchClusterSummary = soc[4];
        sCpuFreqRangeSummary = soc[5];
        sCpuGovernor = soc[6];
        sCpuCores = soc[7];
        sCpuSupportedAbis = "arm64-v8a, armeabi-v7a, armeabi";
        sCpuTypeDesc = soc[12];
        sCpuBogoMips = soc[13];
    }

    public static void applyDeviceProfile(String brand, String model, String manufacturer,
                                          String device, String product, String hardware,
                                          String board, String fingerprint, String androidId) {
        if (brand != null && !brand.isEmpty()) sBrand = brand;
        if (model != null && !model.isEmpty()) sDeviceModel = model;
        if (manufacturer != null && !manufacturer.isEmpty()) sManufacturer = manufacturer;
        if (device != null && !device.isEmpty()) sDeviceId = device;
        if (product != null && !product.isEmpty()) sProduct = product;
        if (hardware != null && !hardware.isEmpty()) sSocHardware = hardware;
        if (board != null && !board.isEmpty()) sBoard = board;
        if (fingerprint != null && !fingerprint.isEmpty()) sBuildFingerprint = fingerprint;
        if (androidId != null && !androidId.isEmpty()) sAndroidId = androidId;
        populateCpuProfileForHardware(sSocHardware, sBoard, sGpuVendor, sGpuRenderer, Math.abs(sAndroidId.hashCode()));
        applyCurrentIdentityToSystem();
    }

    private static String randomHex(Random rnd, int len) {
        StringBuilder sb = new StringBuilder(len);
        for (int i = 0; i < len; i++) {
            sb.append(Integer.toHexString(rnd.nextInt(16)));
        }
        return sb.toString();
    }

    private static String randomDigits(Random rnd, int len) {
        StringBuilder sb = new StringBuilder(len);
        for (int i = 0; i < len; i++) {
            sb.append((char) ('0' + rnd.nextInt(10)));
        }
        return sb.toString();
    }

    private static String generateLuhnImei(Random rnd) {
        String[] tacs = new String[]{
                "35847210", "35291847", "35674109", "35910284",
                "86492017", "86710394", "35481920", "35739104"
        };
        String base14 = tacs[rnd.nextInt(tacs.length)] + randomDigits(rnd, 6);
        int sum = 0;
        for (int i = 0; i < 14; i++) {
            int d = base14.charAt(i) - '0';
            if (i % 2 == 1) {
                d *= 2;
                if (d > 9) d -= 9;
            }
            sum += d;
        }
        int check = (10 - (sum % 10)) % 10;
        return base14 + check;
    }

    private static String generateRandomMac(Random rnd, boolean locallyAdministered) {
        int b0 = rnd.nextInt(256);
        if (locallyAdministered) {
            b0 = (b0 & 0xFC) | 0x02;
        } else {
            b0 = (b0 & 0xFE);
        }
        return String.format(Locale.US, "%02X:%02X:%02X:%02X:%02X:%02X",
                b0, rnd.nextInt(256), rnd.nextInt(256),
                rnd.nextInt(256), rnd.nextInt(256), rnd.nextInt(256));
    }

    public static void wipeApplicationDataAndCaches(Context context) {
        if (context == null) return;
        try {
            // 0. Wipe isolated in-app accounts & sandboxed settings so no previous login session survives
            synchronized (SANDBOXED_APP_ACCOUNTS) {
                SANDBOXED_APP_ACCOUNTS.clear();
            }
            SANDBOXED_ACCOUNT_PASSWORDS.clear();
            SANDBOXED_ACCOUNT_USERDATA.clear();
            SANDBOXED_ACCOUNT_TOKENS.clear();
            EmbeddedGmsCore.clearTokenCache();
            SANDBOXED_SETTINGS_STORE.clear();
            proxyAccountManagerOnContext(context);
            try {
                context.getSharedPreferences("phantom_standalone_runtime", Context.MODE_PRIVATE)
                        .edit().remove("sandboxed_accounts_json").commit();
            } catch (Throwable ignored) {}

            // 1. Wipe all AndroidKeyStore cryptographic keys/tokens for this app
            try {
                java.security.KeyStore ks = java.security.KeyStore.getInstance("AndroidKeyStore");
                ks.load(null);
                Enumeration<String> aliases = ks.aliases();
                if (aliases != null) {
                    while (aliases.hasMoreElements()) {
                        String alias = aliases.nextElement();
                        try {
                            ks.deleteEntry(alias);
                        } catch (Throwable ignored) {}
                    }
                }
            } catch (Throwable ignored) {}

            // 2. Clear WebView Cookies, WebStorage, HTTP Auth & Form Database BEFORE deleting directories on disk
            // (ONLY if Chromium provider is already loaded so we never initialize/recreate app_webview during cold clear)
            if (isWebViewProviderLoaded() || !TRACKED_WEBVIEWS.isEmpty()) {
                try {
                    CookieManager.getInstance().removeAllCookies(null);
                    CookieManager.getInstance().removeSessionCookies(null);
                    CookieManager.getInstance().flush();
                } catch (Throwable ignored) {}
                try {
                    WebStorage.getInstance().deleteAllData();
                } catch (Throwable ignored) {}
                try {
                    WebViewDatabase wvDb = WebViewDatabase.getInstance(context);
                    if (wvDb != null) {
                        wvDb.clearHttpAuthUsernamePassword();
                        wvDb.clearFormData();
                    }
                } catch (Throwable ignored) {}
                synchronized (TRACKED_WEBVIEWS) {
                    for (WebView wv : TRACKED_WEBVIEWS.keySet()) {
                        if (wv != null) {
                            try {
                                wv.clearCache(true);
                                wv.clearHistory();
                                wv.clearFormData();
                            } catch (Throwable ignored) {}
                        }
                    }
                }
            }

            // 3. Clear in-memory SharedPreferences cache in ContextImpl so SDKs cannot read cached tokens
            clearInMemorySharedPreferencesCache(context);

            // 4. Wipe all internal app data roots (ApplicationInfo.dataDir, getDataDir, and filesDir parent)
            Set<String> wipedRoots = new LinkedHashSet<String>();
            ApplicationInfo ai = context.getApplicationInfo();
            if (ai != null && ai.dataDir != null) {
                File dataDirFile = new File(ai.dataDir);
                wipedRoots.add(dataDirFile.getAbsolutePath());
                wipeDataRootDirectory(context, dataDirFile);
            }
            try {
                File filesDir = context.getFilesDir();
                if (filesDir != null && filesDir.getParentFile() != null) {
                    File filesParent = filesDir.getParentFile();
                    if (wipedRoots.add(filesParent.getAbsolutePath())) {
                        wipeDataRootDirectory(context, filesParent);
                    }
                }
            } catch (Throwable ignored) {}
            if (Build.VERSION.SDK_INT >= 24) {
                try {
                    File api24DataDir = context.getDataDir();
                    if (api24DataDir != null && wipedRoots.add(api24DataDir.getAbsolutePath())) {
                        wipeDataRootDirectory(context, api24DataDir);
                    }
                } catch (Throwable ignored) {}
            }

            // 5. Also wipe Device-Protected Storage (Direct Boot storage used by Google/Firebase/WorkManager/Meta SDKs)
            if (Build.VERSION.SDK_INT >= 24) {
                try {
                    Context dpCtx = context.createDeviceProtectedStorageContext();
                    if (dpCtx != null) {
                        clearInMemorySharedPreferencesCache(dpCtx);
                        File dpDataDir = dpCtx.getDataDir();
                        if (dpDataDir != null && dpDataDir.exists()) {
                            wipeDataRootDirectory(dpCtx, dpDataDir);
                        }
                    }
                } catch (Throwable ignored) {}
            }

            // 6. Wipe External Caches and External Files (all volumes)
            try {
                File extCache = context.getExternalCacheDir();
                if (extCache != null) deleteRecursively(extCache, false);
                File extFiles = context.getExternalFilesDir(null);
                if (extFiles != null) deleteRecursively(extFiles, false);
                if (Build.VERSION.SDK_INT >= 19) {
                    File[] extCaches = context.getExternalCacheDirs();
                    if (extCaches != null) {
                        for (File ec : extCaches) {
                            if (ec != null) deleteRecursively(ec, false);
                        }
                    }
                    File[] extFilesDirs = context.getExternalFilesDirs(null);
                    if (extFilesDirs != null) {
                        for (File ef : extFilesDirs) {
                            if (ef != null) deleteRecursively(ef, false);
                        }
                    }
                }
            } catch (Throwable ignored) {}

            // 7. Clear clipboard if it holds pasteboard tracking tokens
            try {
                ClipboardManager cm = (ClipboardManager) context.getSystemService(Context.CLIPBOARD_SERVICE);
                if (cm != null) {
                    if (Build.VERSION.SDK_INT >= 28) {
                        cm.clearPrimaryClip();
                    } else {
                        cm.setPrimaryClip(ClipData.newPlainText("", ""));
                    }
                }
            } catch (Throwable ignored) {}
        } catch (Throwable ignored) {}
    }

    private static void wipeDataRootDirectory(Context context, File dataDir) {
        if (dataDir == null || !dataDir.exists()) return;
        // 1. Wipe SharedPreferences (except phantom_standalone_runtime.xml)
        File prefsDir = new File(dataDir, "shared_prefs");
        if (prefsDir.exists() && prefsDir.isDirectory()) {
            File[] files = prefsDir.listFiles();
            if (files != null) {
                for (File f : files) {
                    String name = f.getName();
                    if ("phantom_standalone_runtime.xml".equals(name) || "phantom_standalone_runtime.bak".equals(name)) {
                        continue;
                    }
                    if (name.endsWith(".xml")) {
                        String prefName = name.substring(0, name.length() - 4);
                        try {
                            context.getSharedPreferences(prefName, Context.MODE_PRIVATE).edit().clear().commit();
                        } catch (Throwable ignored) {}
                    }
                    try {
                        if (Build.VERSION.SDK_INT >= 24) {
                            String prefName = name.endsWith(".xml") ? name.substring(0, name.length() - 4) : name;
                            context.deleteSharedPreferences(prefName);
                        }
                    } catch (Throwable ignored) {}
                    try {
                        f.delete();
                    } catch (Throwable ignored) {}
                }
            }
        }

        // 2. Wipe ALL SQLite Databases (including WorkManager & Room databases so zero old state survives)
        File dbDir = new File(dataDir, "databases");
        if (dbDir.exists() && dbDir.isDirectory()) {
            File[] dbs = dbDir.listFiles();
            if (dbs != null) {
                for (File db : dbs) {
                    try {
                        String dbName = db.getName();
                        if (db.isFile()) {
                            if (!dbName.endsWith("-wal") && !dbName.endsWith("-shm") && !dbName.endsWith("-journal")) {
                                try {
                                    context.deleteDatabase(dbName);
                                } catch (Throwable ignoredDel) {}
                            }
                            db.delete();
                        } else {
                            deleteRecursively(db, true);
                        }
                    } catch (Throwable ignored) {}
                }
            }
        }

        // 3. Wipe internal files directory (strictly preserving split modules, native libraries, and permanent identity vault!)
        File filesDir = new File(dataDir, "files");
        if (filesDir.exists() && filesDir.isDirectory()) {
            File[] children = filesDir.listFiles();
            if (children != null) {
                for (File child : children) {
                    if (child == null) continue;
                    String cName = child.getName().toLowerCase(Locale.US);
                    if (isPreservedCodeOrSplitDir(cName)) {
                        continue; // Keep extracted split resource APKs, splitcompat, and permanent identity vault intact!
                    }
                    deleteRecursively(child, true);
                }
            }
        }

        // 4. Wipe ALL other data subdirectories (including no_backup, app_webview, app_light_prefs,
        // app_mmkv, datastore, cache, code_cache non-dex files), strictly leaving lib and splitcompat intact!
        File[] allTopChildren = dataDir.listFiles();
        if (allTopChildren != null) {
            for (File topChild : allTopChildren) {
                if (topChild == null) continue;
                String topName = topChild.getName();
                if ("lib".equals(topName) || "shared_prefs".equals(topName) ||
                        "databases".equals(topName) || "files".equals(topName)) {
                    continue;
                }
                if (isPreservedCodeOrSplitDir(topName)) {
                    continue;
                }
                deleteRecursively(topChild, true);
            }
        }
    }

    private static boolean isPreservedCodeOrSplitDir(String name) {
        if (name == null) return false;
        String lower = name.toLowerCase(Locale.US);
        return lower.equals("lib") ||
                lower.equals("code_cache") ||
                lower.equals("oat") ||
                lower.startsWith("phantom_splits") ||
                lower.equals("splitcompat") ||
                lower.equals(".phantom_permanent_identity.json") ||
                lower.equals("phantom_standalone_runtime.xml") ||
                lower.equals("phantom_standalone_runtime.bak");
    }

    /**
     * Cleans any orphaned SQLite WAL/SHM/Journal files left behind when a database was wiped
     * or closed mid-transaction, preventing Room / SQLite lock hangs on subsequent cold launches.
     */
    private static void cleanupOrphanedDatabaseWalFiles(Context context) {
        if (context == null) return;
        try {
            ApplicationInfo ai = context.getApplicationInfo();
            if (ai == null || ai.dataDir == null) return;
            File dbDir = new File(ai.dataDir, "databases");
            if (!dbDir.exists() || !dbDir.isDirectory()) return;
            File[] files = dbDir.listFiles();
            if (files == null) return;
            for (File f : files) {
                if (f == null || !f.isFile()) continue;
                String name = f.getName();
                String baseDbName = null;
                if (name.endsWith("-wal")) {
                    baseDbName = name.substring(0, name.length() - 4);
                } else if (name.endsWith("-shm")) {
                    baseDbName = name.substring(0, name.length() - 4);
                } else if (name.endsWith("-journal")) {
                    baseDbName = name.substring(0, name.length() - 8);
                }
                if (baseDbName != null) {
                    File mainDb = new File(dbDir, baseDbName);
                    if (!mainDb.exists() || mainDb.length() == 0L) {
                        try { f.delete(); } catch (Throwable ignored) {}
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    @SuppressWarnings("unchecked")
    private static void clearInMemorySharedPreferencesCache(Context context) {
        try {
            Class<?> ctxImplClass = Class.forName("android.app.ContextImpl");
            Field cacheField = findFieldRecursive(ctxImplClass, "sSharedPrefsCache");
            if (cacheField != null) {
                cacheField.setAccessible(true);
                Object cacheObj = cacheField.get(null);
                if (cacheObj instanceof Map) {
                    Map<?, ?> outerMap = (Map<?, ?>) cacheObj;
                    for (Object innerVal : outerMap.values()) {
                        if (innerVal instanceof Map) {
                            Map<?, ?> innerMap = (Map<?, ?>) innerVal;
                            for (Map.Entry<?, ?> entry : innerMap.entrySet()) {
                                Object keyObj = entry.getKey();
                                String keyName = (keyObj instanceof File) ? ((File) keyObj).getName() : String.valueOf(keyObj);
                                if (keyName != null && keyName.contains("phantom_standalone_runtime")) continue;
                                Object spImpl = entry.getValue();
                                if (spImpl != null) {
                                    try {
                                        Field mMapField = findFieldRecursive(spImpl.getClass(), "mMap");
                                        if (mMapField != null) {
                                            mMapField.setAccessible(true);
                                            Object mMap = mMapField.get(spImpl);
                                            if (mMap instanceof Map) {
                                                try {
                                                    ((Map<?, ?>) mMap).clear();
                                                } catch (Throwable unmod) {
                                                    mMapField.set(spImpl, new HashMap<String, Object>());
                                                }
                                            }
                                        }
                                    } catch (Throwable ignoredSp) {}
                                }
                            }
                        }
                    }
                    outerMap.clear();
                } else if (cacheObj != null && cacheObj.getClass().getName().contains("ArrayMap")) {
                    Method clearMethod = findMethodRecursive(cacheObj.getClass(), "clear");
                    if (clearMethod != null) {
                        clearMethod.setAccessible(true);
                        clearMethod.invoke(cacheObj);
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    private static void deleteRecursively(File fileOrDir, boolean deleteSelf) {
        if (fileOrDir == null || !fileOrDir.exists()) return;
        String name = fileOrDir.getName();
        if (isPreservedCodeOrSplitDir(name)) return;
        if (fileOrDir.isDirectory()) {
            File[] children = fileOrDir.listFiles();
            if (children != null) {
                for (File child : children) {
                    if (child == null) continue;
                    String cName = child.getName().toLowerCase(Locale.US);
                    if (isPreservedCodeOrSplitDir(cName) ||
                            cName.endsWith(".apk") || cName.endsWith(".so") ||
                            cName.endsWith(".dex") || cName.endsWith(".odex") || cName.endsWith(".vdex")) {
                        continue;
                    }
                    deleteRecursively(child, true);
                }
            }
        }
        if (deleteSelf) {
            String lower = name.toLowerCase(Locale.US);
            if (!lower.endsWith(".apk") && !lower.endsWith(".so") &&
                    !lower.endsWith(".dex") && !lower.endsWith(".odex") && !lower.endsWith(".vdex")) {
                try {
                    fileOrDir.delete();
                } catch (Throwable ignored) {}
            }
        }
    }

