    public static void randomizeDeviceIdentityAndWipeAppData(final Context context) {
        randomizeDeviceIdentityAndWipeAppData(context, null);
    }

    private static void randomizeDeviceIdentityAndWipeAppData(final Context context, final TextView[] overlayTextRefs) {
        final Context ctx = (context != null) ? context : sAppContext;
        if (ctx == null) {
            sIsClearingInProgress = false;
            return;
        }
        try {
            Random rnd = new Random(System.nanoTime() ^ (System.currentTimeMillis() * 31L) ^ UUID.randomUUID().getMostSignificantBits());

            // 1. Kill sibling processes first so background services (:nodex/:mqtt/:browser) cannot overwrite wiped files,
            // then perform 100% Deep Clean of all app data, accounts, databases, no_backup, webview, prefs, keystores, and caches
            killAllOtherAppProcesses(ctx);
            wipeApplicationDataAndCaches(ctx);

            // 2. Generate 100% brand-new unique device identity & CPU/SoC/GPU hardware profile in memory
            generateFreshRandomIdentityInMemory();
            sUserClearTimestampMs = System.currentTimeMillis();
            sBuiltTimestampMs = Math.max(sBuiltTimestampMs, sUserClearTimestampMs);

            // 3. Pick a fresh location spot, pin it so host telemetry doesn't overwrite it, and reset steps
            int locIdx = (sZoneSlotIndex + 1 + rnd.nextInt(FRESH_ZONES.length - 1)) % FRESH_ZONES.length;
            sZoneSlotIndex = locIdx;
            sLatitude = FRESH_ZONES[locIdx][0] + ((rnd.nextDouble() - 0.5) * 0.008);
            sLongitude = FRESH_ZONES[locIdx][1] + ((rnd.nextDouble() - 0.5) * 0.008);
            sLocationLabel = FRESH_ZONE_LABELS[locIdx];
            sUserCustomMapPinned = true;
            sUserCustomMapPinTimestamp = System.currentTimeMillis();
            sStepsCount = 0;
            sDistanceMeters = 0.0;

            // 4. Persist all 45+ unique identity & CPU parameters to SharedPreferences AND all 3 permanent Vault layers
            try {
                SharedPreferences sp = ctx.getSharedPreferences("phantom_standalone_runtime", Context.MODE_PRIVATE);
                saveCurrentIdentityToPrefs(sp, true);
            } catch (Throwable ignored) {}

            persistLocationAndStepsPreference();
            persistRuntimeIdentityEverywhere(ctx);
            pushLocationToActiveListeners(ctx);
            updateCapturedMapViews(createSyntheticLocation("gps"), true);
            scanActiveViewsForMapsAndTrackables();
            refreshAllHudViews();

            // Update on-screen confirmation overlay with the newly generated unique identity & CPU!
            if (overlayTextRefs != null && overlayTextRefs.length >= 3) {
                try {
                    overlayTextRefs[0].setText(tr("✅ 100% Deep Clean & New Device Set!", "✅ ১০০% ডিপ ক্লিন ও নতুন ডিভাইস সেট সম্পন্ন!", "✅ १००% डीप क्लीन और नया डिवाइस सेट पूर्ण!"));
                    overlayTextRefs[1].setText("📱 " + sDeviceModel + " • ⚙️ " + sSocModelCode);
                    if (overlayTextRefs.length >= 4 && overlayTextRefs[3] != null) {
                        overlayTextRefs[3].setText("🔑 ID: " + sAndroidId.substring(0, 8) + " • GPU: " + sGpuRenderer);
                    }
                    overlayTextRefs[2].setText("📍 " + sLocationLabel + tr(" • Opening in fresh process...", " • নতুন প্রসেসে ওপেন হচ্ছে...", " • नई प्रोसेस में खुल रहा है..."));
                } catch (Throwable ignored) {}
            }

            Toast.makeText(ctx,
                    tr("✅ Deep Clean & 100% New Unique Device Set!\n📱 ", "✅ ডিপ ক্লিন ও ১০০% নতুন ইউনিক ডিভাইস স্থায়ীভাবে সেট সম্পন্ন!\n📱 ", "✅ डीप क्लीन और १००% नया यूनिक डिवाइस सेट पूर्ण!\n📱 ") + sDeviceModel + " (" + sSocModelCode + ")" +
                            "\n🔑 ID: " + sAndroidId.substring(0, 8) + " • GPU: " + sGpuRenderer +
                            "\n📍 " + sLocationLabel + tr("\n(Restarting app with new identity...)", "\n(অ্যাপ নতুন তথ্যে রিস্টার্ট হচ্ছে...)", "\n(ऐप नई जानकारी के साथ रीस्टार्ट हो रहा है...)"),
                    Toast.LENGTH_LONG).show();

            // Restart into a 100% fresh OS process after brief visual confirmation so ZERO in-memory singletons or native caches survive!
            new Handler(Looper.getMainLooper()).postDelayed(new Runnable() {
                @Override
                public void run() {
                    sIsClearingInProgress = false;
                    try {
                        // Kill any respawned sibling processes first, then final pre-exit sweep of any files flushed by dying threads
                        killAllOtherAppProcesses(ctx);
                        wipeApplicationDataAndCaches(ctx);
                        SharedPreferences sp = ctx.getSharedPreferences("phantom_standalone_runtime", Context.MODE_PRIVATE);
                        saveCurrentIdentityToPrefs(sp, true);
                        persistRuntimeIdentityEverywhere(ctx);
                    } catch (Throwable ignored) {}

                    try {
                        Activity act = findActiveActivity(ctx);
                        Intent launchIntent = ctx.getPackageManager().getLaunchIntentForPackage(ctx.getPackageName());
                        if (launchIntent == null && act != null) {
                            launchIntent = new Intent(act.getIntent());
                        }
                        if (launchIntent != null) {
                            launchIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_CLEAR_TASK);
                            // Schedule failsafe AlarmManager PendingIntent (+500ms) in case startActivity + killProcess races on slow ROMs
                            try {
                                int piFlags = PendingIntent.FLAG_CANCEL_CURRENT | (Build.VERSION.SDK_INT >= 23 ? PendingIntent.FLAG_IMMUTABLE : 0);
                                PendingIntent restartPi = PendingIntent.getActivity(ctx, 99182, launchIntent, piFlags);
                                android.app.AlarmManager am = (android.app.AlarmManager) ctx.getSystemService(Context.ALARM_SERVICE);
                                if (am != null && restartPi != null) {
                                    am.setExact(android.app.AlarmManager.ELAPSED_REALTIME, SystemClock.elapsedRealtime() + 500L, restartPi);
                                }
                            } catch (Throwable ignoredAlarm) {}

                            if (act != null && !act.isFinishing()) {
                                act.startActivity(launchIntent);
                                act.finishAffinity();
                            } else {
                                ctx.startActivity(launchIntent);
                            }
                            killAllOtherAppProcesses(ctx);
                            android.os.Process.killProcess(android.os.Process.myPid());
                            System.exit(0);
                            return;
                        }
                    } catch (Throwable ignored) {}
                    killAllOtherAppProcesses(ctx);
                    android.os.Process.killProcess(android.os.Process.myPid());
                    System.exit(0);
                }
            }, 520L);
        } catch (Throwable ignored) {
            sIsClearingInProgress = false;
        }
    }

    private static void clearSettingsNameValueCache(Class<?> settingsTableClass) {
        if (settingsTableClass == null) return;
        try {
            Field cacheField = findFieldRecursive(settingsTableClass, "sNameValueCache");
            if (cacheField == null) return;
            cacheField.setAccessible(true);
            Object cacheObj = cacheField.get(null);
            if (cacheObj == null) return;
            Field valuesField = findFieldRecursive(cacheObj.getClass(), "mValues");
            if (valuesField != null) {
                valuesField.setAccessible(true);
                Object mapObj = valuesField.get(cacheObj);
                if (mapObj instanceof Map) {
                    ((Map<?, ?>) mapObj).clear();
                }
            }
            Field cpField = findFieldRecursive(cacheObj.getClass(), "mContentProvider");
            if (cpField != null) {
                cpField.setAccessible(true);
                Object cpHolder = cpField.get(cacheObj);
                if (cpHolder != null) {
                    Field providerField = findFieldRecursive(cpHolder.getClass(), "mContentProvider");
                    if (providerField != null) {
                        providerField.setAccessible(true);
                        Object realProvider = providerField.get(cpHolder);
                        if (realProvider != null && !isPhantomProxy(realProvider)) {
                            providerField.set(cpHolder, wrapSettingsIContentProvider(realProvider));
                        }
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    private static void wrapExistingActivityThreadSettingsProviders() {
        try {
            Class<?> atClass = Class.forName("android.app.ActivityThread");
            Method currentAtMethod = atClass.getDeclaredMethod("currentActivityThread");
            currentAtMethod.setAccessible(true);
            Object at = currentAtMethod.invoke(null);
            if (at == null) return;
            Field mapField = findFieldRecursive(atClass, "mProviderMap");
            if (mapField == null) return;
            mapField.setAccessible(true);
            Object mapObj = mapField.get(at);
            if (!(mapObj instanceof Map)) return;
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) mapObj).entrySet()) {
                Object key = entry.getKey();
                Object clientRecord = entry.getValue();
                if (clientRecord == null) continue;
                String keyStr = String.valueOf(key);
                Field mNamesField = findFieldRecursive(clientRecord.getClass(), "mNames");
                if (mNamesField != null) {
                    mNamesField.setAccessible(true);
                    Object namesObj = mNamesField.get(clientRecord);
                    if (namesObj instanceof String[]) {
                        for (String n : (String[]) namesObj) {
                            if (n != null) keyStr += "|" + n;
                        }
                    }
                }
                Field mProviderField = findFieldRecursive(clientRecord.getClass(), "mProvider");
                if (mProviderField == null) continue;
                mProviderField.setAccessible(true);
                clearFinalModifier(mProviderField);
                Object curProvider = mProviderField.get(clientRecord);
                if (curProvider == null || isPhantomProxy(curProvider)) continue;
                if (keyStr.contains("settings")) {
                    mProviderField.set(clientRecord, wrapSettingsIContentProvider(curProvider));
                } else if (keyStr.contains("gservices")) {
                    mProviderField.set(clientRecord, wrapGservicesIContentProvider(curProvider));
                }
            }
            aliasOriginalAuthoritiesInProviderMap();
        } catch (Throwable ignored) {}
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private static void aliasOriginalAuthoritiesInProviderMap() {
        if (sOriginalPackageName == null || sOriginalPackageName.isEmpty() ||
                sStandalonePackageName == null || sStandalonePackageName.isEmpty() ||
                sOriginalPackageName.equals(sStandalonePackageName)) {
            return;
        }
        try {
            Class<?> atClass = Class.forName("android.app.ActivityThread");
            Method currentAtMethod = atClass.getDeclaredMethod("currentActivityThread");
            currentAtMethod.setAccessible(true);
            Object at = currentAtMethod.invoke(null);
            if (at == null) return;
            Field mapField = findFieldRecursive(atClass, "mProviderMap");
            if (mapField == null) return;
            mapField.setAccessible(true);
            Object mapObj = mapField.get(at);
            if (!(mapObj instanceof Map)) return;
            Map rawMap = (Map) mapObj;
            String pkgSuffix = sStandalonePackageName.startsWith(sOriginalPackageName)
                    ? sStandalonePackageName.substring(sOriginalPackageName.length())
                    : ".ghostdevice";
            if (pkgSuffix.isEmpty()) pkgSuffix = ".ghostdevice";

            Map<Object, Object> toInsert = new HashMap<Object, Object>();
            for (Object entryObj : new ArrayList<Object>(rawMap.entrySet())) {
                Map.Entry entry = (Map.Entry) entryObj;
                Object key = entry.getKey();
                Object clientRecord = entry.getValue();
                if (key == null || clientRecord == null) continue;
                Field authField = findFieldRecursive(key.getClass(), "authority");
                Field userIdField = findFieldRecursive(key.getClass(), "userId");
                if (authField == null || userIdField == null) continue;
                authField.setAccessible(true);
                userIdField.setAccessible(true);
                Object authObj = authField.get(key);
                if (!(authObj instanceof String)) continue;
                String auth = (String) authObj;
                int userId = userIdField.getInt(key);

                List<String> aliases = new ArrayList<String>(2);
                if (auth.endsWith(pkgSuffix) && auth.length() > pkgSuffix.length()) {
                    String stripped = auth.substring(0, auth.length() - pkgSuffix.length());
                    aliases.add(stripped);
                    if (stripped.contains(sStandalonePackageName)) {
                        aliases.add(stripped.replace(sStandalonePackageName, sOriginalPackageName));
                    }
                } else if (auth.contains(sStandalonePackageName)) {
                    aliases.add(auth.replace(sStandalonePackageName, sOriginalPackageName));
                }
                for (int i = 0; i < aliases.size(); i++) {
                    String aliasAuth = aliases.get(i);
                    if (aliasAuth != null && !aliasAuth.isEmpty() && !aliasAuth.equals(auth)) {
                        try {
                            Constructor<?> keyCtor = key.getClass().getDeclaredConstructor(String.class, int.class);
                            keyCtor.setAccessible(true);
                            Object aliasKey = keyCtor.newInstance(aliasAuth, Integer.valueOf(userId));
                            if (!rawMap.containsKey(aliasKey)) {
                                toInsert.put(aliasKey, clientRecord);
                            }
                        } catch (Throwable ignoredCtor) {}
                    }
                }
            }
            if (!toInsert.isEmpty()) {
                rawMap.putAll(toInsert);
            }
        } catch (Throwable ignored) {}
    }

    private static void applyDeviceIdentitySpoofing(Context context) {
        if (!sIdentitySpoofEnabled && !sRootBypassFeatureEnabled && !sStepWalkFeatureEnabled) {
            return;
        }
        try {
            disablePropertyInvalidatedCachesOnClass(Settings.Secure.class);
            disablePropertyInvalidatedCachesOnClass(Settings.Global.class);
            disablePropertyInvalidatedCachesOnClass(Settings.System.class);
            try {
                disablePropertyInvalidatedCachesOnClass(Class.forName("android.provider.Settings$Config"));
            } catch (Throwable ignored) {}

            clearSettingsNameValueCache(Settings.Secure.class);
            clearSettingsNameValueCache(Settings.Global.class);
            clearSettingsNameValueCache(Settings.System.class);
            wrapExistingActivityThreadSettingsProviders();

            if (sIdentitySpoofEnabled) {
                injectSettingsCache(Settings.Secure.class, new String[][]{
                        {"android_id", sAndroidId},
                        {"advertising_id", sAdvertisingId},
                        {"limit_ad_tracking", "0"},
                        {"bluetooth_name", sBluetoothName},
                        {"bluetooth_address", sBluetoothAddress}
                });
                injectSettingsCache(Settings.Global.class, new String[][]{
                        {"device_name", sDeviceModel},
                        {"bluetooth_name", sBluetoothName},
                        {"boot_count", "12"},
                        {"auto_time", "1"},
                        {"auto_time_zone", "1"}
                });
                injectSettingsCache(Settings.System.class, new String[][]{
                        {"android_id", sAndroidId},
                        {"device_name", sDeviceModel},
                        {"bluetooth_name", sBluetoothName}
                });
            }
            if (sStepWalkFeatureEnabled || sRootBypassFeatureEnabled) {
                injectSettingsCache(Settings.Secure.class, new String[][]{
                        {"mock_location", "0"},
                        {"allow_mock_location", "0"},
                        {"mock_location_app", ""}
                });
                injectSettingsCache(Settings.Global.class, new String[][]{
                        {"allow_mock_location", "0"},
                        {"mock_location", "0"}
                });
            }
            if (sRootBypassFeatureEnabled) {
                injectSettingsCache(Settings.Secure.class, new String[][]{
                        {"adb_enabled", "0"},
                        {"development_settings_enabled", "0"},
                        {"install_non_market_apps", "0"},
                        {"accessibility_enabled", "0"},
                        {"touch_exploration_enabled", "0"},
                        {"enabled_accessibility_services", ""}
                });
                injectSettingsCache(Settings.Global.class, new String[][]{
                        {"adb_enabled", "0"},
                        {"development_settings_enabled", "0"},
                        {"usb_mass_storage_enabled", "0"},
                        {"wait_for_debugger", "0"},
                        {"debug_app", ""}
                });
                injectSettingsCache(Settings.System.class, new String[][]{
                        {"adb_enabled", "0"},
                        {"development_settings_enabled", "0"}
                });
            }
        } catch (Throwable ignored) {}
    }

    private static final Set<Object> PHANTOM_PROXIES =
            Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Object, Boolean>()));

    private static boolean isPhantomProxy(Object obj) {
        return obj != null && PHANTOM_PROXIES.contains(obj);
    }

    private static ClassLoader getSafeClassLoader() {
        ClassLoader cl = StandaloneRuntimeEngine.class.getClassLoader();
        if (cl != null) return cl;
        cl = Thread.currentThread().getContextClassLoader();
        if (cl != null) return cl;
        return ClassLoader.getSystemClassLoader();
    }

    private static <T> T markPhantomProxy(T proxy) {
        if (proxy != null) {
            PHANTOM_PROXIES.add(proxy);
        }
        return proxy;
    }

    private static void disableSinglePropertyInvalidatedCacheObject(Object cacheObj) {
        if (cacheObj == null) return;
        try {
            Method dfcp = findMethodRecursive(cacheObj.getClass(), "disableForCurrentProcess");
            if (dfcp != null && dfcp.getParameterTypes().length == 0) {
                dfcp.setAccessible(true);
                dfcp.invoke(cacheObj);
            }
        } catch (Throwable ignored) {}
        try {
            Method disableLocal = findMethodRecursive(cacheObj.getClass(), "disableLocal");
            if (disableLocal != null && disableLocal.getParameterTypes().length == 0) {
                disableLocal.setAccessible(true);
                disableLocal.invoke(cacheObj);
            }
        } catch (Throwable ignored) {}
        try {
            Method clearMethod = findMethodRecursive(cacheObj.getClass(), "clear");
            if (clearMethod != null && clearMethod.getParameterTypes().length == 0) {
                clearMethod.setAccessible(true);
                clearMethod.invoke(cacheObj);
            }
        } catch (Throwable ignored) {}
        try {
            Field disabledField = findFieldRecursive(cacheObj.getClass(), "mDisabled");
            if (disabledField != null) {
                disabledField.setAccessible(true);
                disabledField.setBoolean(cacheObj, true);
            }
        } catch (Throwable ignored) {}
        try {
            Field innerCacheField = findFieldRecursive(cacheObj.getClass(), "mCache");
            if (innerCacheField != null) {
                innerCacheField.setAccessible(true);
                Object innerMap = innerCacheField.get(cacheObj);
                if (innerMap instanceof Map) {
                    ((Map<?, ?>) innerMap).clear();
                } else if (innerMap != null) {
                    Method innerClear = findMethodRecursive(innerMap.getClass(), "clear");
                    if (innerClear != null && innerClear.getParameterTypes().length == 0) {
                        innerClear.setAccessible(true);
                        innerClear.invoke(innerMap);
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    private static final Set<Class<?>> PIC_DISABLED_CLASSES =
            Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Class<?>, Boolean>()));
    private static final AtomicBoolean GLOBAL_PIC_KEYS_DISABLED = new AtomicBoolean(false);

    private static void disablePropertyInvalidatedCachesOnClass(Class<?> cls) {
        if (cls == null || !PIC_DISABLED_CLASSES.add(cls)) return;
        disablePropertyInvalidatedCachesOnInstanceOrClass(cls, null);
    }

    private static void disablePropertyInvalidatedCachesOnInstanceOrClass(Class<?> cls, Object instance) {
        if (cls == null) return;
        try {
            Class<?> cur = cls;
            while (cur != null && cur != Object.class) {
                Field[] fields = cur.getDeclaredFields();
                for (int i = 0; i < fields.length; i++) {
                    Field f = fields[i];
                    boolean isStatic = java.lang.reflect.Modifier.isStatic(f.getModifiers());
                    if (!isStatic && instance == null) continue;
                    String typeName = f.getType().getName();
                    String fieldName = f.getName();
                    if (typeName.contains("PropertyInvalidatedCache") ||
                            typeName.contains("IpcDataCache") ||
                            fieldName.contains("AccountsForUserCache") ||
                            fieldName.contains("AccountsAndVisibility") ||
                            fieldName.toLowerCase(Locale.US).contains("account")) {
                        try {
                            f.setAccessible(true);
                            Object cacheObj = f.get(isStatic ? null : instance);
                            disableSinglePropertyInvalidatedCacheObject(cacheObj);
                        } catch (Throwable ignoredField) {}
                    }
                }
                cur = cur.getSuperclass();
            }
            Class<?>[] inner = cls.getDeclaredClasses();
            if (inner != null) {
                for (int i = 0; i < inner.length; i++) {
                    Field[] innerFields = inner[i].getDeclaredFields();
                    for (int j = 0; j < innerFields.length; j++) {
                        Field f = innerFields[j];
                        if (java.lang.reflect.Modifier.isStatic(f.getModifiers())) {
                            String typeName = f.getType().getName();
                            if (typeName.contains("PropertyInvalidatedCache") || typeName.contains("IpcDataCache")) {
                                try {
                                    f.setAccessible(true);
                                    Object cacheObj = f.get(null);
                                    disableSinglePropertyInvalidatedCacheObject(cacheObj);
                                } catch (Throwable ignoredInner) {}
                            }
                        }
                    }
                }
            }
            // Explicitly disable global PropertyInvalidatedCache / IpcDataCache keys for AccountManager once per process
            if (GLOBAL_PIC_KEYS_DISABLED.compareAndSet(false, true)) {
                String[] keys = new String[]{
                        "cache_key.system_server.accounts_data",
                        "cache_key.system_server.account_data",
                        "cache_key.system_server.account_user_data",
                        "cache_key.system_server.accounts_and_visibility_for_package",
                        "cache_key.accounts_data",
                        "cache_key.account_data",
                        "cache_key.account_user_data",
                        "cache_key.accounts_for_user",
                        "cache_key.accounts_and_visibility_for_package",
                        "accounts_data",
                        "account_data",
                        "account_user_data",
                        "accounts_for_user"
                };
                String[] cacheClassNames = new String[]{
                        "android.app.PropertyInvalidatedCache",
                        "android.os.IpcDataCache"
                };
                for (String cacheClsName : cacheClassNames) {
                    try {
                        Class<?> cCls = Class.forName(cacheClsName);
                        Method dfcpStr = findMethodRecursive(cCls, "disableForCurrentProcess", String.class);
                        if (dfcpStr != null) {
                            dfcpStr.setAccessible(true);
                            for (String k : keys) {
                                try { dfcpStr.invoke(null, k); } catch (Throwable ignoredKey) {}
                            }
                        }
                        Method dfcpZero = findMethodRecursive(cCls, "disableForCurrentProcess");
                        if (dfcpZero != null && dfcpZero.getParameterTypes().length == 0) {
                            try {
                                dfcpZero.setAccessible(true);
                                dfcpZero.invoke(null);
                            } catch (Throwable ignoredZero) {}
                        }
                    } catch (Throwable ignoredCls) {}
                }
            }
        } catch (Throwable ignored) {}
    }

    private static String accountMapKey(Account acc) {
        if (acc == null) return "";
        return (acc.type != null ? acc.type : "") + "|" + (acc.name != null ? acc.name : "");
    }

    private static void loadSandboxedAccountsFromPrefs(SharedPreferences prefs) {
        synchronized (SANDBOXED_APP_ACCOUNTS) {
            SANDBOXED_APP_ACCOUNTS.clear();
            SANDBOXED_ACCOUNT_PASSWORDS.clear();
            SANDBOXED_ACCOUNT_USERDATA.clear();
            SANDBOXED_ACCOUNT_TOKENS.clear();
            if (prefs == null) return;
            try {
                String raw = prefs.getString("sandboxed_accounts_json", "");
                if (raw != null && !raw.isEmpty()) {
                    JSONArray arr = new JSONArray(raw);
                    for (int i = 0; i < arr.length(); i++) {
                        JSONObject o = arr.optJSONObject(i);
                        if (o != null) {
                            String name = o.optString("name", "");
                            String type = o.optString("type", "");
                            if (!name.isEmpty() && !type.isEmpty()) {
                                Account acc = new Account(name, type);
                                SANDBOXED_APP_ACCOUNTS.add(acc);
                                String aKey = accountMapKey(acc);
                                if (o.has("password")) {
                                    SANDBOXED_ACCOUNT_PASSWORDS.put(aKey, o.optString("password", ""));
                                }
                                JSONObject udObj = o.optJSONObject("userData");
                                if (udObj != null) {
                                    Map<String, String> udMap = Collections.synchronizedMap(new HashMap<String, String>());
                                    Iterator<String> keys = udObj.keys();
                                    while (keys.hasNext()) {
                                        String k = keys.next();
                                        if (k != null && !udObj.isNull(k)) {
                                            udMap.put(k, udObj.optString(k, ""));
                                        }
                                    }
                                    SANDBOXED_ACCOUNT_USERDATA.put(aKey, udMap);
                                }
                                JSONObject tokObj = o.optJSONObject("tokens");
                                if (tokObj != null) {
                                    Map<String, String> tokMap = new ConcurrentHashMap<String, String>();
                                    Iterator<String> tKeys = tokObj.keys();
                                    while (tKeys.hasNext()) {
                                        String tk = tKeys.next();
                                        if (tk != null && !tokObj.isNull(tk)) {
                                            tokMap.put(tk, tokObj.optString(tk, ""));
                                        }
                                    }
                                    SANDBOXED_ACCOUNT_TOKENS.put(aKey, tokMap);
                                }
                            }
                        }
                    }
                }
            } catch (Throwable ignored) {}
        }
    }

    private static void persistSandboxedAccountsToPrefs() {
        Context ctx = sAppContext;
        if (ctx == null) return;
        try {
            JSONArray arr = new JSONArray();
            synchronized (SANDBOXED_APP_ACCOUNTS) {
                for (Account acc : SANDBOXED_APP_ACCOUNTS) {
                    if (acc != null) {
                        JSONObject o = new JSONObject();
                        o.put("name", acc.name);
                        o.put("type", acc.type);
                        String aKey = accountMapKey(acc);
                        String pwd = SANDBOXED_ACCOUNT_PASSWORDS.get(aKey);
                        if (pwd != null) {
                            o.put("password", pwd);
                        }
                        Map<String, String> udMap = SANDBOXED_ACCOUNT_USERDATA.get(aKey);
                        if (udMap != null && !udMap.isEmpty()) {
                            JSONObject udObj = new JSONObject();
                            synchronized (udMap) {
                                for (Map.Entry<String, String> e : udMap.entrySet()) {
                                    if (e.getKey() != null && e.getValue() != null) {
                                        udObj.put(e.getKey(), e.getValue());
                                    }
                                }
                            }
                            o.put("userData", udObj);
                        }
                        Map<String, String> tokMap = SANDBOXED_ACCOUNT_TOKENS.get(aKey);
                        if (tokMap != null && !tokMap.isEmpty()) {
                            JSONObject tokObj = new JSONObject();
                            for (Map.Entry<String, String> te : tokMap.entrySet()) {
                                if (te.getKey() != null && te.getValue() != null) {
                                    tokObj.put(te.getKey(), te.getValue());
                                }
                            }
                            if (tokObj.length() > 0) {
                                o.put("tokens", tokObj);
                            }
                        }
                        arr.put(o);
                    }
                }
            }
            ctx.getSharedPreferences("phantom_standalone_runtime", Context.MODE_PRIVATE)
                    .edit()
                    .putString("sandboxed_accounts_json", arr.toString())
                    .apply();
        } catch (Throwable ignored) {}
    }

    private static Account[] getFilteredSandboxedAccounts(String accountType) {
        synchronized (SANDBOXED_APP_ACCOUNTS) {
            if (SANDBOXED_APP_ACCOUNTS.isEmpty()) {
                return new Account[0];
            }
            if (accountType == null || accountType.isEmpty()) {
                return SANDBOXED_APP_ACCOUNTS.toArray(new Account[0]);
            }
            List<Account> filtered = new ArrayList<Account>();
            for (Account acc : SANDBOXED_APP_ACCOUNTS) {
                if (acc != null && accountType.equals(acc.type)) {
                    filtered.add(acc);
                }
            }
            return filtered.toArray(new Account[0]);
        }
    }

    // ---- Package-private bridge helpers for EmbeddedGmsCore ----
    static Account[] getSandboxedGoogleAccounts() {
        return getFilteredSandboxedAccounts(EmbeddedGmsCore.GOOGLE_ACCOUNT_TYPE);
    }

    static void saveSandboxedGoogleAccountForGms(String email, String masterToken, Map<String, String> userData) {
        if (email == null || email.trim().isEmpty()) return;
        Account acc = new Account(email.trim(), EmbeddedGmsCore.GOOGLE_ACCOUNT_TYPE);
        String accKey = accountMapKey(acc);
        synchronized (SANDBOXED_APP_ACCOUNTS) {
            SANDBOXED_APP_ACCOUNTS.remove(acc);
            SANDBOXED_APP_ACCOUNTS.add(0, acc);
        }
        if (masterToken != null && !masterToken.isEmpty()) {
            SANDBOXED_ACCOUNT_PASSWORDS.put(accKey, masterToken);
        }
        if (userData != null && !userData.isEmpty()) {
            Map<String, String> uMap = SANDBOXED_ACCOUNT_USERDATA.get(accKey);
            if (uMap == null) {
                uMap = new ConcurrentHashMap<String, String>();
                SANDBOXED_ACCOUNT_USERDATA.put(accKey, uMap);
            }
            uMap.putAll(userData);
        }
        persistSandboxedAccountsToPrefs();
    }

    static void clearAllSandboxedGoogleAccountsForGms() {
        synchronized (SANDBOXED_APP_ACCOUNTS) {
            Iterator<Account> it = SANDBOXED_APP_ACCOUNTS.iterator();
            while (it.hasNext()) {
                Account a = it.next();
                if (a != null && EmbeddedGmsCore.GOOGLE_ACCOUNT_TYPE.equals(a.type)) {
                    String k = accountMapKey(a);
                    SANDBOXED_ACCOUNT_PASSWORDS.remove(k);
                    SANDBOXED_ACCOUNT_USERDATA.remove(k);
                    SANDBOXED_ACCOUNT_TOKENS.remove(k);
                    it.remove();
                }
            }
        }
        persistSandboxedAccountsToPrefs();
        refreshAllHudViews();
    }

    static String getSandboxedAccountPasswordForGms(String email, String type) {
        if (email == null || type == null) return null;
        return SANDBOXED_ACCOUNT_PASSWORDS.get(accountMapKey(new Account(email, type)));
    }

    static String getSandboxedAccountTokenForGms(String email, String type, String tokenType) {
        if (email == null || type == null || tokenType == null) return null;
        Map<String, String> tMap = SANDBOXED_ACCOUNT_TOKENS.get(accountMapKey(new Account(email, type)));
        return tMap != null ? tMap.get(tokenType) : null;
    }

    static void putSandboxedAccountTokenForGms(String email, String type, String tokenType, String token) {
        if (email == null || type == null || tokenType == null || token == null) return;
        String accKey = accountMapKey(new Account(email, type));
        Map<String, String> tMap = SANDBOXED_ACCOUNT_TOKENS.get(accKey);
        if (tMap == null) {
            tMap = new ConcurrentHashMap<String, String>();
            SANDBOXED_ACCOUNT_TOKENS.put(accKey, tMap);
        }
        tMap.put(tokenType, token);
        persistSandboxedAccountsToPrefs();
    }

    static void clearSandboxedAccountTokenForGms(String tokToRemove) {
        if (tokToRemove == null || tokToRemove.isEmpty()) return;
        for (Map<String, String> tMap : SANDBOXED_ACCOUNT_TOKENS.values()) {
            if (tMap != null) {
                Iterator<Map.Entry<String, String>> it = tMap.entrySet().iterator();
                while (it.hasNext()) {
                    if (tokToRemove.equals(it.next().getValue())) {
                        it.remove();
                    }
                }
            }
        }
        persistSandboxedAccountsToPrefs();
    }

