    private static void injectWebViewLocationRecenterScript(final WebView wv, final double lat, final double lng) {
        if (wv == null) return;
        try {
            final String js = String.format(Locale.US,
                    "(function(){try{" +
                            "window.__phLat=%.8f;window.__phLng=%.8f;" +
                            "var pos={coords:{latitude:%.8f,longitude:%.8f,accuracy:3.2,altitude:14.5,heading:0,speed:0},timestamp:Date.now()};" +
                            "if(window.__phWatchCallbacks){for(var i=0;i<window.__phWatchCallbacks.length;i++){try{window.__phWatchCallbacks[i](pos);}catch(e){}}}" +
                            "if(window.map&&typeof window.map.setView==='function'){try{window.map.setView([%.8f,%.8f]);}catch(e){}}" +
                            "if(window.map&&typeof window.map.panTo==='function'){try{window.map.panTo([%.8f,%.8f]);}catch(e){}}" +
                            "if(window.google&&window.google.maps&&window.__gmap){try{window.__gmap.panTo({lat:%.8f,lng:%.8f});}catch(e){}}" +
                            "}catch(e){}})();",
                    lat, lng, lat, lng, lat, lng, lat, lng, lat, lng
            );
            if (Build.VERSION.SDK_INT >= 19) {
                wv.evaluateJavascript(js, null);
            } else {
                wv.loadUrl(js);
            }
        } catch (Throwable ignored) {}
    }

    private static boolean isHardwareDiagnosticApp() {
        String p1 = (sOriginalPackageName != null) ? sOriginalPackageName.toLowerCase(Locale.US) : "";
        String p2 = (sStandalonePackageName != null) ? sStandalonePackageName.toLowerCase(Locale.US) : "";
        String combined = p1 + " " + p2;
        return combined.contains("deviceinfo") ||
                combined.contains("device_info") ||
                combined.contains("devcheck") ||
                combined.contains("cpuz") ||
                combined.contains("cpu_z") ||
                combined.contains("aida64") ||
                combined.contains("droidhardware") ||
                combined.contains("hwinfo") ||
                combined.contains("deviceid") ||
                combined.contains("device_id") ||
                combined.contains("identifier") ||
                combined.contains("benchmark") ||
                combined.contains("geekbench") ||
                combined.contains("antutu") ||
                combined.contains("ytheekshana") ||
                combined.contains("inkwired") ||
                combined.contains("finalwire") ||
                combined.contains("zausan") ||
                combined.contains("evozi") ||
                combined.contains("inware") ||
                combined.contains("castro") ||
                combined.contains("devicetools") ||
                combined.contains("hardwareinfo") ||
                combined.contains("systeminfo") ||
                combined.contains("phoneinfo") ||
                combined.contains("mydevice");
    }

    private static void scanActiveViewsForMapsAndTrackables() {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            Handler h = sEngineMainHandler != null ? sEngineMainHandler : new Handler(Looper.getMainLooper());
            h.post(new Runnable() {
                @Override
                public void run() {
                    scanActiveViewsForMapsAndTrackablesOnUiThread();
                }
            });
            return;
        }
        scanActiveViewsForMapsAndTrackablesOnUiThread();
    }

    private static void scanActiveViewsForMapsAndTrackablesOnUiThread() {
        try {
            synchronized (ACTIVE_HUD_VIEWS) {
                for (int i = ACTIVE_HUD_VIEWS.size() - 1; i >= 0; i--) {
                    HudCanvasView hud = ACTIVE_HUD_VIEWS.get(i).get();
                    if (hud != null) {
                        ViewParent vp = hud.getParent();
                        if (vp instanceof ViewGroup) {
                            scanViewHierarchyForTrackables((ViewGroup) vp);
                        }
                    }
                }
            }
            List<Activity> acts;
            synchronized (TRACKED_ACTIVITIES) {
                acts = new ArrayList<Activity>(TRACKED_ACTIVITIES);
            }
            for (Activity act : acts) {
                if (act == null || act.isFinishing()) continue;
                if (sAdBypassFeatureEnabled) {
                    if (isStandaloneAdActivity(act.getClass().getName())) {
                        fastForwardAndCompleteStandaloneAdActivity(act);
                        continue;
                    } else {
                        scanAndProxyStandaloneAdsOnActivity(act);
                    }
                }
                Window w = act.getWindow();
                if (w != null) {
                    View decor = w.peekDecorView();
                    if (decor != null) {
                        scanViewHierarchyForTrackables(decor);
                    }
                }
                if (sStepWalkFeatureEnabled) {
                    try {
                        Class<?> faCls = Class.forName("androidx.fragment.app.FragmentActivity");
                        if (faCls.isInstance(act)) {
                            Method getFmM = faCls.getMethod("getSupportFragmentManager");
                            Object fm = getFmM.invoke(act);
                            if (fm != null) {
                                Method getFragsM = fm.getClass().getMethod("getFragments");
                                Object fragsList = getFragsM.invoke(fm);
                                if (fragsList instanceof List) {
                                    for (Object frag : (List<?>) fragsList) {
                                        if (frag == null) continue;
                                        String fragClsName = frag.getClass().getName();
                                        if (!fragClsName.contains("Map") && !fragClsName.contains("map")) continue;
                                        try {
                                            Method gma = frag.getClass().getMethod("getMapAsync", Class.forName("com.google.android.gms.maps.OnMapReadyCallback", false, frag.getClass().getClassLoader()));
                                            Class<?> cbCls = Class.forName("com.google.android.gms.maps.OnMapReadyCallback", false, frag.getClass().getClassLoader());
                                            Object cb = Proxy.newProxyInstance(frag.getClass().getClassLoader(), new Class<?>[]{cbCls}, new InvocationHandler() {
                                                @Override
                                                public Object invoke(Object p, Method m, Object[] a) {
                                                    if ("onMapReady".equals(m.getName()) && a != null && a.length > 0 && a[0] != null) {
                                                        CAPTURED_GOOGLE_MAPS.add(a[0]);
                                                        updateGoogleMapCamera(a[0], sLatitude, sLongitude, true);
                                                    }
                                                    return null;
                                                }
                                            });
                                            gma.invoke(frag, cb);
                                        } catch (Throwable ignoredGma) {}
                                    }
                                }
                            }
                        }
                    } catch (Throwable ignoredFrag) {}
                }
            }
        } catch (Throwable ignored) {}
    }

    private static void scanViewHierarchyForTrackables(View root) {
        if (Looper.myLooper() != Looper.getMainLooper()) return;
        boolean collectDiagText = sIdentitySpoofEnabled && isHardwareDiagnosticApp();
        if (!collectDiagText && !sIdentitySpoofEnabled && !sStepWalkFeatureEnabled && !sSpeedFeatureEnabled && !sAdBypassFeatureEnabled) {
            return;
        }
        List<TextView> collectedTextViews = collectDiagText ? new ArrayList<TextView>(64) : null;
        scanViewHierarchyBounded(root, new int[]{0}, collectedTextViews);
        if (collectedTextViews != null && !collectedTextViews.isEmpty()) {
            sanitizeDiagnosticAndIdentityTextViews(collectedTextViews);
        }
    }

    private static void scanViewHierarchyBounded(View root, int[] budget, List<TextView> collectedTextViews) {
        if (root == null || budget[0] > 320) return;
        budget[0]++;
        if (isSpeedScaled()) {
            try {
                Animation anim = root.getAnimation();
                if (anim != null && !TRACKED_ANIMATIONS.containsKey(anim)) {
                    TRACKED_ANIMATIONS.put(anim, new long[]{SystemClock.elapsedRealtime()});
                }
            } catch (Throwable ignored) {}
        }
        if (sStepWalkFeatureEnabled) {
            try {
                String clsName = root.getClass().getName();
                if (clsName.contains("MapView") || clsName.startsWith("org.osmdroid.views") || clsName.contains("mapbox") || clsName.contains("maplibre")) {
                    if (CAPTURED_MAP_VIEWS.add(root)) {
                        fixOsmdroidAndMapConfig(root.getContext());
                        Set<Object> mapVisited = Collections.newSetFromMap(new WeakHashMap<Object, Boolean>());
                        inspectObjectForListeners(root, 0, mapVisited);
                        updateCapturedMapViews(createSyntheticLocation("gps"), true);
                    }
                }
            } catch (Throwable ignored) {}
        }
        if (sAdBypassFeatureEnabled) {
            try {
                String adClsName = root.getClass().getName();
                if (adClsName.equals("com.google.android.gms.ads.AdView") ||
                        adClsName.equals("com.google.android.gms.ads.BaseAdView") ||
                        adClsName.equals("com.google.android.gms.ads.admanager.AdManagerAdView") ||
                        adClsName.startsWith("com.applovin.mediation.ads.MaxAdView") ||
                        adClsName.startsWith("com.unity3d.services.banners.BannerView") ||
                        adClsName.startsWith("com.ironsource.mediationsdk.IronSourceBannerLayout") ||
                        adClsName.equals("com.facebook.ads.AdView")) {
                    root.setAlpha(0f);
                    ViewGroup.LayoutParams lp = root.getLayoutParams();
                    if (lp != null && lp.height != 0) {
                        lp.height = 0;
                        root.setLayoutParams(lp);
                    }
                    return;
                }
            } catch (Throwable ignored) {}
        }
        if (root instanceof Chronometer) {
            Chronometer ch = (Chronometer) root;
            if (!TRACKED_CHRONOMETERS.containsKey(ch)) {
                TRACKED_CHRONOMETERS.put(ch, new long[]{SystemClock.elapsedRealtime()});
            }
        } else if (root instanceof WebView) {
            WebView wv = (WebView) root;
            if (!sWebViewFactoryProxyInstalled && sIdentitySpoofEnabled) {
                installWebViewFactoryAndBuildInfoHook();
            }
            if (!TRACKED_WEBVIEWS.containsKey(wv)) {
                TRACKED_WEBVIEWS.put(wv, sSpeedMultiplier);
                try {
                    String u = wv.getUrl();
                    if (u != null) TRACKED_WEBVIEW_URLS.put(wv, u);
                } catch (Throwable ignoredUrl) {}
                injectWebViewSpeedScript(wv, sSpeedMultiplier);
            }
        } else if (collectedTextViews != null && root instanceof TextView && !(root instanceof EditText)) {
            if (collectedTextViews.size() < 160) {
                collectedTextViews.add((TextView) root);
            }
        }
        if (root instanceof ViewGroup) {
            ViewGroup vg = (ViewGroup) root;
            if ("phantom_clear_confirm_overlay".equals(vg.getTag())
                    || "phantom_standalone_hud_tag".equals(vg.getTag())
                    || "phantom_cookies_toast_banner".equals(vg.getTag())) {
                return;
            }
            int count = vg.getChildCount();
            for (int i = 0; i < count; i++) {
                if (budget[0] > 320) break;
                scanViewHierarchyBounded(vg.getChildAt(i), budget, collectedTextViews);
            }
        }
    }

    /**
     * Dynamically updates diagnostic / Device Info screens (including CPU top card, Processor,
     * CPU Architecture, CPU Hardware, CPU Governor, Cores, CPU Frequency, GPU Renderer/Vendor/Version,
     * and Device/System rows) so clicking "🔄 ক্লিয়ার" changes 100% of displayed hardware/CPU/identity values.
     */
    private static void sanitizeDiagnosticAndIdentityTextViews(List<TextView> textViews) {
        if (textViews == null || textViews.isEmpty()) return;
        try {
            int n = textViews.size();
            for (int i = 0; i < n; i++) {
                TextView tv = textViews.get(i);
                if (tv == null) continue;
                CharSequence cs = tv.getText();
                if (cs == null) continue;
                String txt = cs.toString().trim();
                if (txt.isEmpty()) continue;
                String lower = txt.toLowerCase(Locale.US);

                // 1. Replace "Unable to retrieve CPU information. Please try again" with active randomized CPU summary
                if (lower.contains("unable to retrieve cpu information")) {
                    if (!txt.equals(sCpuTopCardSummary)) {
                        tv.setText(sCpuTopCardSummary);
                    }
                    // Hide any sibling "Retry" button inside the same card container
                    ViewParent parent = tv.getParent();
                    if (parent instanceof ViewGroup) {
                        ViewGroup vg = (ViewGroup) parent;
                        for (int c = 0; c < vg.getChildCount(); c++) {
                            View sibling = vg.getChildAt(c);
                            if (sibling != tv && sibling instanceof TextView) {
                                CharSequence sibCs = ((TextView) sibling).getText();
                                if (sibCs != null && sibCs.toString().toLowerCase(Locale.US).contains("retry")) {
                                    sibling.setVisibility(View.GONE);
                                }
                            } else if (sibling instanceof ViewGroup) {
                                ViewGroup subVg = (ViewGroup) sibling;
                                for (int sc = 0; sc < subVg.getChildCount(); sc++) {
                                    View subChild = subVg.getChildAt(sc);
                                    if (subChild instanceof TextView) {
                                        CharSequence subCs = ((TextView) subChild).getText();
                                        if (subCs != null && subCs.toString().toLowerCase(Locale.US).contains("retry")) {
                                            sibling.setVisibility(View.GONE);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    continue;
                }
                if (lower.equals("retry")) {
                    ViewParent parent = tv.getParent();
                    if (parent instanceof ViewGroup) {
                        ViewGroup vg = (ViewGroup) parent;
                        for (int c = 0; c < vg.getChildCount(); c++) {
                            View sibling = vg.getChildAt(c);
                            if (sibling instanceof TextView && sibling != tv) {
                                CharSequence sibCs = ((TextView) sibling).getText();
                                if (sibCs != null && (sibCs.toString().contains(sSocModelCode) || sibCs.toString().toLowerCase(Locale.US).contains("snapdragon") || sibCs.toString().toLowerCase(Locale.US).contains("dimensity") || sibCs.toString().toLowerCase(Locale.US).contains("exynos") || sibCs.toString().toLowerCase(Locale.US).contains("tensor"))) {
                                    tv.setVisibility(View.GONE);
                                }
                            }
                        }
                    }
                }

                // 2. Replace any leaked real host model or fingerprint directly inside any TextView
                if (sRealHostModel != null && sRealHostModel.length() >= 3 && txt.contains(sRealHostModel) && !sDeviceModel.contains(sRealHostModel)) {
                    String replaced = txt.replace(sRealHostModel, sDeviceModel);
                    if (sRealHostBrand != null && sRealHostBrand.length() >= 3) {
                        replaced = replaced.replace(sRealHostBrand, sBrand);
                    }
                    tv.setText(replaced);
                } else if (sRealHostFingerprint != null && sRealHostFingerprint.length() >= 8 && txt.contains(sRealHostFingerprint)) {
                    tv.setText(txt.replace(sRealHostFingerprint, sBuildFingerprint));
                }

                // 3. Check label -> value pairs (adjacent TextView in same row/column or next TextView in list)
                if (i + 1 < n) {
                    TextView nextTv = textViews.get(i + 1);
                    if (nextTv != null && isSameOrSiblingRowContainer(tv, nextTv)) {
                        String replacement = resolveSpoofedValueForLabel(lower);
                        if (replacement != null && !replacement.isEmpty()) {
                            CharSequence curValCs = nextTv.getText();
                            String curVal = curValCs != null ? curValCs.toString() : "";
                            if (!replacement.equals(curVal)) {
                                nextTv.setText(replacement);
                            }
                            i++; // Skip the value TextView we just updated
                        }
                    }
                }
            }
        } catch (Throwable ignored) {}
    }

    private static boolean isSameOrSiblingRowContainer(TextView labelTv, TextView valueTv) {
        if (labelTv == null || valueTv == null) return false;
        ViewParent p1 = labelTv.getParent();
        ViewParent p2 = valueTv.getParent();
        if (p1 == null || p2 == null) return false;
        if (p1 == p2) return true;
        return p1.getParent() != null && p1.getParent() == p2.getParent();
    }

    private static String resolveSpoofedValueForLabel(String lowerLabel) {
        if (lowerLabel == null || lowerLabel.isEmpty()) return null;
        switch (lowerLabel) {
            case "processor":
            case "soc":
            case "soc model":
            case "chipset":
            case "cpu model":
            case "cpu":
                return sCpuProcessorName;
            case "cpu architecture":
            case "clusters":
                return sCpuArchClusterSummary;
            case "supported abis":
            case "supported abi":
            case "instruction sets":
                return sCpuSupportedAbis;
            case "cpu hardware":
                return sSocHardware + " (" + sSocModelCode + ")";
            case "cpu type":
                return sCpuTypeDesc;
            case "cpu governor":
            case "scaling governor":
                return sCpuGovernor;
            case "cores":
            case "cpu cores":
                return sCpuCores;
            case "cpu frequency":
            case "frequency range":
                return sCpuFreqRangeSummary;
            case "bogomips":
                return sCpuBogoMips;
            case "gpu renderer":
                return sGpuRenderer;
            case "gpu vendor":
                return sGpuVendor;
            case "gpu version":
            case "opengl version":
                return sGpuVersion;
            case "device name":
            case "model":
            case "device model":
            case "market name":
            case "marketing name":
                return sDeviceModel;
            case "manufacturer":
                return sManufacturer;
            case "brand":
                return sBrand;
            case "device":
            case "codename":
                return sDeviceId;
            case "product":
                return sProduct;
            case "board":
                return sBoard;
            case "hardware":
                return sSocHardware;
            case "android device id":
            case "android id":
            case "ssa id":
                return sAndroidId;
            case "google services framework id":
            case "gsf id":
                return sGsfId;
            case "advertising id":
            case "google advertising id":
            case "gaid":
                return sAdvertisingId;
            case "widevine id":
            case "device unique id":
            case "drm id":
                return sWidevineDrmId;
            case "imei":
            case "imei 1":
                return sImei;
            case "meid":
                return sMeid;
            case "imsi":
            case "subscriber id":
                return sSimImsi;
            case "iccid":
            case "sim serial":
                return sSimIccid;
            case "wifi mac":
            case "mac address":
            case "wi-fi mac address":
                return sMacAddress;
            case "bluetooth address":
            case "bt mac":
                return sBluetoothAddress;
            case "ip address":
            case "ipv4":
                return sIpAddress;
            case "build fingerprint":
            case "fingerprint":
                return sBuildFingerprint;
            case "build number":
            case "build id":
                return sBuildNumber;
            case "bootloader":
                return sBootloaderVersion;
            case "baseband":
            case "radio":
                return sBasebandVersion;
            case "kernel version":
            case "kernel":
                return sKernelVersion;
            case "security patch":
            case "security patch level":
                return sSecurityPatch;
            case "serial":
            case "serial number":
            case "hardware serial":
                return sSerialNumber;
            case "usb debugging":
                return "Off";
            case "root status":
            case "rooted":
                return "No";
            case "selinux":
            case "selinux status":
                return "Enforcing";
            default:
                return null;
        }
    }

    private static final Set<Application> REGISTERED_APPS =
            Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Application, Boolean>()));

    private static final Application.ActivityLifecycleCallbacks HUD_LIFECYCLE_CALLBACKS =
            new Application.ActivityLifecycleCallbacks() {
                @Override
                public void onActivityCreated(Activity activity, Bundle savedInstanceState) {
                    if (activity != null) {
                        if (!ACTIVITY_CREATED_TIME_MS.containsKey(activity)) {
                            ACTIVITY_CREATED_TIME_MS.put(activity, SystemClock.elapsedRealtime());
                        }
                        TRACKED_ACTIVITIES.add(activity);
                        if (isYouTubeTarget() && !isYouTubeShellClassName(activity.getClass().getName())) {
                            sYouTubeNonShellActivityActive = true;
                        }
                    }
                    applySplitResourcesAndWrapperToContext(activity);
                    proxyAccountManagerOnContext(activity);
                    neutralizePairipLicenseCheckIfLoaded(activity);
                    if (sAdBypassFeatureEnabled && activity != null && !isYouTubeTarget()) {
                        installStandaloneAdMobClientApiProxy(activity);
                        if (isStandaloneAdActivity(activity.getClass().getName())) {
                            hideStandaloneAdActivityWindow(activity);
                            return;
                        } else {
                            scanAndProxyStandaloneAdsOnActivity(activity);
                        }
                    }
                    if (sStepWalkFeatureEnabled) {
                        installLocationManagerProxy(activity);
                        fixOsmdroidAndMapConfig(activity);
                    }
                    scheduleSplashActivityStallWatchdogIfNeeded(activity);
                }

                @Override
                public void onActivityStarted(Activity activity) {
                    applySplitResourcesAndWrapperToContext(activity);
                    if (sAdBypassFeatureEnabled && activity != null && !isYouTubeTarget()) {
                        if (isStandaloneAdActivity(activity.getClass().getName())) {
                            hideStandaloneAdActivityWindow(activity);
                            return;
                        } else {
                            scanAndProxyStandaloneAdsOnActivity(activity);
                        }
                    }
                    scheduleSplashActivityStallWatchdogIfNeeded(activity);
                }

                @Override
                public void onActivityResumed(final Activity activity) {
                    if (activity != null) {
                        String actCls = activity.getClass().getName();
                        if (!actCls.contains("VMDisplayActivity") && !actCls.startsWith("com.clone.android.dual.space")) {
                            sLastResumedActivityRef = new WeakReference<Activity>(activity);
                            if (!ACTIVITY_CREATED_TIME_MS.containsKey(activity)) {
                                ACTIVITY_CREATED_TIME_MS.put(activity, SystemClock.elapsedRealtime());
                            }
                            TRACKED_ACTIVITIES.add(activity);
                        }
                    }
                    applySplitResourcesAndWrapperToContext(activity);
                    proxyAccountManagerOnContext(activity);
                    neutralizePairipLicenseCheckIfLoaded(activity);
                    installActivityTaskManagerAntiExitProxy();
                    if (isYouTubeTarget()) {
                        installYouTubeSystemHooks(activity);
                    }
                    if (sStepWalkFeatureEnabled) {
                        installLocationManagerProxy(activity);
                        fixOsmdroidAndMapConfig(activity);
                    }
                    if (sSpeedFeatureEnabled) {
                        applyValueAnimatorScale(sSpeedMultiplier, false);
                    }
                    if (sAdBypassFeatureEnabled && activity != null && !isYouTubeTarget()) {
                        installStandaloneAdMobClientApiProxy(activity);
                        if (isStandaloneAdActivity(activity.getClass().getName())) {
                            fastForwardAndCompleteStandaloneAdActivity(activity);
                            return;
                        } else {
                            scanAndProxyStandaloneAdsOnActivity(activity);
                        }
                    }
                    // Post HUD attachment after onResume completes so we NEVER call getDecorView()
                    // before the Activity calls requestWindowFeature() or setContentView()!
                    new Handler(Looper.getMainLooper()).post(new Runnable() {
                        @Override
                        public void run() {
                            attachHudToActivity(activity);
                            enforceStandaloneLicenseOnUiThread();
                            showStandaloneAdminBroadcastDialogIfNeeded();
                        }
                    });
                    scheduleSplashActivityStallWatchdogIfNeeded(activity);
                    triggerAsyncFirestoreLicenseSync(activity, false);
                }

                @Override
                public void onActivityPaused(Activity activity) {
                    restoreYouTubeAdMutedAudioIfNeeded();
                }

                @Override
                public void onActivityStopped(Activity activity) {}

                @Override
                public void onActivitySaveInstanceState(Activity activity, Bundle outState) {}

                @Override
                public void onActivityDestroyed(Activity activity) {
                    restoreYouTubeAdMutedAudioIfNeeded();
                    if (activity != null) {
                        synchronized (TRACKED_ACTIVITIES) {
                            TRACKED_ACTIVITIES.remove(activity);
                        }
                    }
                    synchronized (ACTIVE_HUD_VIEWS) {
                        for (int i = ACTIVE_HUD_VIEWS.size() - 1; i >= 0; i--) {
                            HudCanvasView v = ACTIVE_HUD_VIEWS.get(i).get();
                            if (v == null || (activity != null && v.getContext() == activity)) {
                                ACTIVE_HUD_VIEWS.remove(i);
                            }
                        }
                    }
                }
            };

    private static final Set<Activity> COMPLETED_AD_ACTIVITIES =
            Collections.synchronizedSet(Collections.newSetFromMap(new WeakHashMap<Activity, Boolean>()));
    private static final Map<Field, Object> CACHED_STANDALONE_AD_OBJECTS =
            Collections.synchronizedMap(new HashMap<Field, Object>());
