    private interface SlippyMapLocationListener {
        void onLocationChanged(double lat, double lng, boolean isFinalGesture);
    }

    private interface SearchResultsRenderer {
        void renderResults(List<PlaceResult> results, boolean isExplicitButton);
    }

    private static final class PlaceResult {
        final String shortName;
        final String displayName;
        final double lat;
        final double lng;

        PlaceResult(String shortName, String displayName, double lat, double lng) {
            this.shortName = shortName;
            this.displayName = displayName;
            this.lat = lat;
            this.lng = lng;
        }
    }

    private interface SearchPlacesCallback {
        void onResults(List<PlaceResult> results);
    }

    private interface GeocodeCallback {
        void onResolved(String label);
    }

    private static List<PlaceResult> matchWorldPresets(String rawQuery) {
        List<PlaceResult> matches = new ArrayList<PlaceResult>();
        if (rawQuery == null) return matches;
        String q = rawQuery.trim().toLowerCase(Locale.US);
        if (q.isEmpty()) return matches;
        for (int i = 0; i < WORLD_SEARCH_PRESETS.length; i++) {
            String[] wp = WORLD_SEARCH_PRESETS[i];
            if (wp[0].toLowerCase(Locale.US).contains(q) || wp[1].toLowerCase(Locale.US).contains(q)) {
                try {
                    matches.add(new PlaceResult(wp[0], wp[1], Double.parseDouble(wp[2]), Double.parseDouble(wp[3])));
                } catch (Throwable ignored) {}
            }
        }
        return matches;
    }

    private static void searchWorldwidePlacesAsync(final Context context, final String rawQuery, final SearchPlacesCallback callback) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                List<PlaceResult> list = new ArrayList<PlaceResult>();
                String q = rawQuery != null ? rawQuery.trim() : "";
                if (q.isEmpty()) {
                    callback.onResults(list);
                    return;
                }

                // 1. Check direct "lat, lng" input
                try {
                    String[] parts = q.split("[,\\s]+");
                    if (parts.length == 2) {
                        double lat = Double.parseDouble(parts[0]);
                        double lng = Double.parseDouble(parts[1]);
                        if (lat >= -90.0 && lat <= 90.0 && lng >= -180.0 && lng <= 180.0) {
                            String lbl = String.format(Locale.US, "GPS (%.4f, %.4f)", lat, lng);
                            list.add(new PlaceResult(lbl, "Direct Coordinate Pin", lat, lng));
                            callback.onResults(list);
                            return;
                        }
                    }
                } catch (Throwable ignored) {}

                // 2. Include matching world presets at the top (e.g. "usa" -> "New York, USA" / "Times Square, New York, USA")
                list.addAll(matchWorldPresets(q));

                // 3. OpenStreetMap Nominatim Worldwide Search
                HttpURLConnection conn = null;
                try {
                    String urlStr = "https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=8&accept-language="
                            + sAppLanguage + ",en&q="
                            + URLEncoder.encode(q, "UTF-8");
                    conn = (HttpURLConnection) new URL(urlStr).openConnection();
                    conn.setConnectTimeout(4500);
                    conn.setReadTimeout(4500);
                    conn.setRequestProperty("User-Agent", "GhostDeviceMapPicker/3.0 (Android)");
                    if (conn.getResponseCode() == 200) {
                        BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream(), StandardCharsets.UTF_8));
                        StringBuilder sb = new StringBuilder();
                        String line;
                        while ((line = br.readLine()) != null) sb.append(line);
                        br.close();
                        JSONArray arr = new JSONArray(sb.toString());
                        for (int i = 0; i < arr.length(); i++) {
                            JSONObject obj = arr.getJSONObject(i);
                            double lat = obj.optDouble("lat", Double.NaN);
                            double lon = obj.optDouble("lon", Double.NaN);
                            String disp = obj.optString("display_name", "");
                            String nameField = obj.optString("name", "");
                            if (!Double.isNaN(lat) && !Double.isNaN(lon) && !disp.isEmpty()) {
                                String[] split = disp.split(",");
                                String shortLbl = !nameField.isEmpty() ? nameField : split[0].trim();
                                String subLbl = split.length > 1 ? disp.substring(disp.indexOf(',') + 1).trim() : disp;
                                if (subLbl.isEmpty()) subLbl = disp;
                                list.add(new PlaceResult(shortLbl, subLbl, lat, lon));
                            }
                        }
                    }
                } catch (Throwable ignored) {
                } finally {
                    if (conn != null) try { conn.disconnect(); } catch (Throwable ignored) {}
                }

                // 4. Photon Komoot Worldwide Geocoder (runs if Nominatim returned < 3 network items)
                if (list.size() < 4) {
                    HttpURLConnection pConn = null;
                    try {
                        String urlStr = "https://photon.komoot.io/api/?limit=8&q=" + URLEncoder.encode(q, "UTF-8");
                        pConn = (HttpURLConnection) new URL(urlStr).openConnection();
                        pConn.setConnectTimeout(4500);
                        pConn.setReadTimeout(4500);
                        pConn.setRequestProperty("User-Agent", "GhostDeviceMapPicker/3.0 (Android)");
                        if (pConn.getResponseCode() == 200) {
                            BufferedReader br = new BufferedReader(new InputStreamReader(pConn.getInputStream(), StandardCharsets.UTF_8));
                            StringBuilder sb = new StringBuilder();
                            String line;
                            while ((line = br.readLine()) != null) sb.append(line);
                            br.close();
                            JSONObject root = new JSONObject(sb.toString());
                            JSONArray features = root.optJSONArray("features");
                            if (features != null) {
                                for (int i = 0; i < features.length(); i++) {
                                    JSONObject feat = features.getJSONObject(i);
                                    JSONObject geom = feat.optJSONObject("geometry");
                                    JSONObject props = feat.optJSONObject("properties");
                                    if (geom != null && props != null) {
                                        JSONArray coords = geom.optJSONArray("coordinates");
                                        if (coords != null && coords.length() >= 2) {
                                            double lon = coords.optDouble(0, Double.NaN);
                                            double lat = coords.optDouble(1, Double.NaN);
                                            String name = props.optString("name", "");
                                            String city = props.optString("city", props.optString("state", ""));
                                            String country = props.optString("country", "");
                                            String shortLbl = !name.isEmpty() ? name : (!city.isEmpty() ? city : country);
                                            StringBuilder subSb = new StringBuilder();
                                            if (!city.isEmpty() && !city.equals(shortLbl)) subSb.append(city);
                                            if (!country.isEmpty()) {
                                                if (subSb.length() > 0) subSb.append(", ");
                                                subSb.append(country);
                                            }
                                            String subLbl = subSb.length() > 0 ? subSb.toString() : shortLbl;
                                            if (!Double.isNaN(lat) && !Double.isNaN(lon) && !shortLbl.isEmpty()) {
                                                list.add(new PlaceResult(shortLbl, subLbl, lat, lon));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } catch (Throwable ignored) {
                    } finally {
                        if (pConn != null) try { pConn.disconnect(); } catch (Throwable ignored) {}
                    }
                }

                // 5. Fallback: Android Geocoder
                if (list.isEmpty() && context != null && Geocoder.isPresent()) {
                    try {
                        Geocoder geocoder = new Geocoder(context, Locale.getDefault());
                        List<Address> addrs = geocoder.getFromLocationName(q, 6);
                        if (addrs != null) {
                            for (Address a : addrs) {
                                if (a.hasLatitude() && a.hasLongitude()) {
                                    String feat = a.getFeatureName() != null ? a.getFeatureName() : "";
                                    String loc = a.getLocality() != null ? a.getLocality() : (a.getSubAdminArea() != null ? a.getSubAdminArea() : "");
                                    String country = a.getCountryName() != null ? a.getCountryName() : "";
                                    String shortLbl = !loc.isEmpty() ? (feat.isEmpty() ? loc : feat + ", " + loc) : (!feat.isEmpty() ? feat : q);
                                    String full = !country.isEmpty() ? (loc.isEmpty() ? country : loc + ", " + country) : shortLbl;
                                    list.add(new PlaceResult(shortLbl, full, a.getLatitude(), a.getLongitude()));
                                }
                            }
                        }
                    } catch (Throwable ignored) {}
                }

                callback.onResults(list);
            }
        }).start();
    }

    private static void reverseGeocodeAsync(final Context context, final double lat, final double lng, final GeocodeCallback callback) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                String resolved = "";
                HttpURLConnection conn = null;
                try {
                    String urlStr = String.format(Locale.US,
                            "https://nominatim.openstreetmap.org/reverse?format=json&lat=%.6f&lon=%.6f&zoom=16&accept-language=%s,en",
                            lat, lng, sAppLanguage);
                    conn = (HttpURLConnection) new URL(urlStr).openConnection();
                    conn.setConnectTimeout(3500);
                    conn.setReadTimeout(3500);
                    conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Linux; Android 14)");
                    if (conn.getResponseCode() == 200) {
                        BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream(), StandardCharsets.UTF_8));
                        StringBuilder sb = new StringBuilder();
                        String line;
                        while ((line = br.readLine()) != null) sb.append(line);
                        br.close();
                        JSONObject obj = new JSONObject(sb.toString());
                        String disp = obj.optString("display_name", "");
                        if (!disp.isEmpty()) {
                            String[] parts = disp.split(",");
                            resolved = parts.length >= 2 ? (parts[0].trim() + ", " + parts[1].trim()) : parts[0].trim();
                        }
                    }
                } catch (Throwable ignored) {
                } finally {
                    if (conn != null) try { conn.disconnect(); } catch (Throwable ignored) {}
                }

                if (resolved.isEmpty() && context != null && Geocoder.isPresent()) {
                    try {
                        Geocoder g = new Geocoder(context, Locale.getDefault());
                        List<Address> addrs = g.getFromLocation(lat, lng, 1);
                        if (addrs != null && !addrs.isEmpty()) {
                            Address a = addrs.get(0);
                            String sub = a.getSubLocality() != null ? a.getSubLocality() : a.getFeatureName();
                            String city = a.getLocality() != null ? a.getLocality() : a.getCountryName();
                            if (sub != null && city != null) resolved = sub + ", " + city;
                            else if (city != null) resolved = city;
                        }
                    } catch (Throwable ignored) {}
                }

                if (resolved.isEmpty()) {
                    resolved = String.format(Locale.US, "GPS (%.4f, %.4f)", lat, lng);
                }
                callback.onResolved(resolved);
            }
        }).start();
    }

    /**
     * 100% Native Hardware-Accelerated Slippy Map Canvas View.
     * Eliminates WebView / Chromium cold-start initialization hangs and delivers instant (<2ms)
     * dialog opening and 60/120fps touch panning, pinch-to-zoom, tap-to-pin, and multi-server
     * tile caching (Satellite Hybrid `lyrs=y`, Pure Satellite `lyrs=s`, Street Map `lyrs=m`).
     */
    private static final class SlippyMapCanvasView extends View {
        private static final LruCache<String, Bitmap> TILE_MEM_CACHE = new LruCache<String, Bitmap>(180);
        private static final Set<String> IN_FLIGHT_TILES = Collections.synchronizedSet(new LinkedHashSet<String>());
        private static final Map<String, Long> FAILED_TILES = Collections.synchronizedMap(new HashMap<String, Long>());
        private static final ExecutorService TILE_EXECUTOR = Executors.newFixedThreadPool(6, new ThreadFactory() {
            private int seq = 0;
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "Phantom-TileLoader-" + (++seq));
                t.setDaemon(true);
                t.setPriority(Thread.NORM_PRIORITY - 1);
                return t;
            }
        });

        private final AtomicBoolean tileInvalidateScheduled = new AtomicBoolean(false);
        private final Runnable tileInvalidateRunnable = new Runnable() {
            @Override
            public void run() {
                tileInvalidateScheduled.set(false);
                invalidate();
            }
        };

        private final float dp;
        private double centerLat;
        private double centerLng;
        private int zoom = 16;
        private String layer = "hybrid";

        private final Paint bgPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint gridPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint tilePaint = new Paint(Paint.FILTER_BITMAP_FLAG);
        private final Paint pinRingFillPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint pinRingStrokePaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint pinBodyPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint pinBorderPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint badgeBgPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint badgeBorderPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint badgeTextPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint zoomBtnBgPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint zoomBtnBorderPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Paint zoomBtnTextPaint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final Path pinPath = new Path();
        private final Rect srcRect = new Rect();
        private final RectF dstRect = new RectF();
        private final RectF zoomPlusRect = new RectF();
        private final RectF zoomMinusRect = new RectF();
        private final RectF badgeRect = new RectF();

        private boolean isDragging = false;
        private boolean movedDuringTouch = false;
        private float lastTouchX = 0f;
        private float lastTouchY = 0f;
        private float downTouchX = 0f;
        private float downTouchY = 0f;
        private float pinchStartDist = 0f;
        private long lastTapUpMs = 0L;

        private SlippyMapLocationListener locationListener;
        private Runnable tapStartListener;

        SlippyMapCanvasView(Context context, double initLat, double initLng) {
            super(context);
            this.dp = context.getResources().getDisplayMetrics().density;
            this.centerLat = Math.max(-85.0, Math.min(85.0, initLat));
            this.centerLng = initLng;

            bgPaint.setColor(Color.parseColor("#0B1928"));
            gridPaint.setColor(Color.parseColor("#1E00E5FF"));
            gridPaint.setStyle(Paint.Style.STROKE);
            gridPaint.setStrokeWidth(Math.max(1f, 0.8f * dp));

            pinRingFillPaint.setColor(Color.parseColor("#3800E5FF"));
            pinRingFillPaint.setStyle(Paint.Style.FILL);

            pinRingStrokePaint.setColor(Color.parseColor("#00E5FF"));
            pinRingStrokePaint.setStyle(Paint.Style.STROKE);
            pinRingStrokePaint.setStrokeWidth(2f * dp);

            pinBodyPaint.setColor(Color.parseColor("#FF1744"));
            pinBodyPaint.setStyle(Paint.Style.FILL);

            pinBorderPaint.setColor(Color.WHITE);
            pinBorderPaint.setStyle(Paint.Style.STROKE);
            pinBorderPaint.setStrokeWidth(2f * dp);

            badgeBgPaint.setColor(Color.parseColor("#D90B1622"));
            badgeBgPaint.setStyle(Paint.Style.FILL);

            badgeBorderPaint.setColor(Color.parseColor("#00E5FF"));
            badgeBorderPaint.setStyle(Paint.Style.STROKE);
            badgeBorderPaint.setStrokeWidth(Math.max(1f, 1.1f * dp));

            badgeTextPaint.setColor(Color.parseColor("#00E676"));
            badgeTextPaint.setTypeface(Typeface.DEFAULT_BOLD);
            badgeTextPaint.setTextSize(10.5f * dp);

            zoomBtnBgPaint.setColor(Color.parseColor("#EB0B1622"));
            zoomBtnBgPaint.setStyle(Paint.Style.FILL);

            zoomBtnBorderPaint.setColor(Color.parseColor("#00E5FF"));
            zoomBtnBorderPaint.setStyle(Paint.Style.STROKE);
            zoomBtnBorderPaint.setStrokeWidth(1.5f * dp);

            zoomBtnTextPaint.setColor(Color.WHITE);
            zoomBtnTextPaint.setTypeface(Typeface.DEFAULT_BOLD);
            zoomBtnTextPaint.setTextAlign(Paint.Align.CENTER);
            zoomBtnTextPaint.setTextSize(20f * dp);
        }

        void setLocationChangeListener(SlippyMapLocationListener listener) {
            this.locationListener = listener;
        }

        void setOnMapTapStartListener(Runnable listener) {
            this.tapStartListener = listener;
        }

        void setMapLayer(String newLayer) {
            if (newLayer != null && !newLayer.equals(this.layer)) {
                this.layer = newLayer;
                invalidate();
            }
        }

        void flyToLocation(double lat, double lng, int newZoom) {
            this.centerLat = Math.max(-85.0, Math.min(85.0, lat));
            this.centerLng = lng;
            if (newZoom >= 2 && newZoom <= 19) {
                this.zoom = newZoom;
            }
            invalidate();
        }

        void changeZoom(int delta) {
            int next = Math.max(2, Math.min(19, this.zoom + delta));
            if (next != this.zoom) {
                this.zoom = next;
                invalidate();
            }
        }

        private static double lonToTileX(double lon, int z) {
            return ((lon + 180.0) / 360.0) * (1 << z);
        }

        private static double latToTileY(double lat, int z) {
            double rad = Math.toRadians(Math.max(-85.0511, Math.min(85.0511, lat)));
            return (1.0 - Math.log(Math.tan(rad) + (1.0 / Math.cos(rad))) / Math.PI) / 2.0 * (1 << z);
        }

        private static double tileXToLon(double x, int z) {
            return (x / (double) (1 << z)) * 360.0 - 180.0;
        }

        private static double tileYToLat(double y, int z) {
            double n = Math.PI - (2.0 * Math.PI * y) / (double) (1 << z);
            return Math.toDegrees(Math.atan(0.5 * (Math.exp(n) - Math.exp(-n))));
        }

        private static String getTileUrl(int x, int y, int z, String l, boolean fallback) {
            int maxT = 1 << z;
            int tx = ((x % maxT) + maxT) % maxT;
            int sub = Math.abs(tx + y) & 3;
            if ("hybrid".equals(l)) {
                return fallback
                        ? ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/" + z + "/" + y + "/" + tx)
                        : ("https://mt" + sub + ".google.com/vt/lyrs=y&x=" + tx + "&y=" + y + "&z=" + z);
            }
            if ("sat".equals(l)) {
                return fallback
                        ? ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/" + z + "/" + y + "/" + tx)
                        : ("https://mt" + sub + ".google.com/vt/lyrs=s&x=" + tx + "&y=" + y + "&z=" + z);
            }
            return fallback
                    ? ("https://tile.openstreetmap.org/" + z + "/" + tx + "/" + y + ".png")
                    : ("https://mt" + sub + ".google.com/vt/lyrs=m&x=" + tx + "&y=" + y + "&z=" + z);
        }

        private File getTileCacheDir() {
            try {
                Context ctx = getContext();
                if (ctx == null) ctx = sAppContext;
                if (ctx != null) {
                    File d = new File(ctx.getCacheDir(), "phantom_map_tiles");
                    if (!d.exists()) d.mkdirs();
                    return d;
                }
            } catch (Throwable ignored) {}
            return null;
        }

        private Bitmap getOrLoadTile(final int x, final int y, final int z, final String l) {
            int maxT = 1 << z;
            if (y < 0 || y >= maxT) return null;
            final int tx = ((x % maxT) + maxT) % maxT;
            final String key = l + "_" + z + "_" + tx + "_" + y;
            Bitmap cached = TILE_MEM_CACHE.get(key);
            if (cached != null && !cached.isRecycled()) {
                return cached;
            }
            Long failedAt = FAILED_TILES.get(key);
            if (failedAt != null && (SystemClock.elapsedRealtime() - failedAt) < 20000L) {
                return null;
            }
            if (IN_FLIGHT_TILES.add(key)) {
                TILE_EXECUTOR.execute(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            Bitmap bmp = loadTileWithDiskCache(key, tx, y, z, l);
                            if (bmp != null) {
                                FAILED_TILES.remove(key);
                                TILE_MEM_CACHE.put(key, bmp);
                                if (tileInvalidateScheduled.compareAndSet(false, true)) {
                                    postOnAnimation(tileInvalidateRunnable);
                                }
                            } else {
                                FAILED_TILES.put(key, SystemClock.elapsedRealtime());
                            }
                        } catch (Throwable ignored) {
                            FAILED_TILES.put(key, SystemClock.elapsedRealtime());
                        } finally {
                            IN_FLIGHT_TILES.remove(key);
                        }
                    }
                });
            }
            return null;
        }

        private Bitmap loadTileWithDiskCache(String key, int tx, int y, int z, String l) {
            File diskDir = getTileCacheDir();
            if (diskDir != null) {
                File tileFile = new File(diskDir, key + ".bin");
                if (tileFile.exists() && tileFile.length() > 0) {
                    try {
                        Bitmap b = BitmapFactory.decodeFile(tileFile.getAbsolutePath());
                        if (b != null) return b;
                    } catch (Throwable ignored) {}
                }
            }
            byte[] bytes = downloadTileBytes(getTileUrl(tx, y, z, l, false));
            if (bytes == null) {
                bytes = downloadTileBytes(getTileUrl(tx, y, z, l, true));
            }
            if (bytes != null && bytes.length > 0) {
                if (diskDir != null) {
                    try {
                        File tileFile = new File(diskDir, key + ".bin");
                        FileOutputStream fos = new FileOutputStream(tileFile);
                        fos.write(bytes);
                        fos.close();
                    } catch (Throwable ignored) {}
                }
                try {
                    return BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
                } catch (Throwable ignored) {}
            }
            return null;
        }

        private static byte[] downloadTileBytes(String urlStr) {
            HttpURLConnection conn = null;
            InputStream is = null;
            try {
                conn = (HttpURLConnection) new URL(urlStr).openConnection();
                conn.setConnectTimeout(2500);
                conn.setReadTimeout(2500);
                conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/124.0.0.0 Mobile Safari/537.36");
                if (conn.getResponseCode() == 200) {
                    is = conn.getInputStream();
                    ByteArrayOutputStream bos = new ByteArrayOutputStream(16384);
                    byte[] buf = new byte[4096];
                    int r;
                    while ((r = is.read(buf)) != -1) {
                        bos.write(buf, 0, r);
                    }
                    return bos.toByteArray();
                }
            } catch (Throwable ignored) {
            } finally {
                if (is != null) try { is.close(); } catch (Throwable ignored) {}
                if (conn != null) try { conn.disconnect(); } catch (Throwable ignored) {}
            }
            return null;
        }

        @Override
        protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            int w = getWidth();
            int h = getHeight();
            if (w <= 0 || h <= 0) return;

            canvas.drawRect(0f, 0f, w, h, bgPaint);

            // Render 256dp-scaled tiles so labels and roads are crisp on high-DPI screens
            float tileSizePx = 256f * Math.max(1f, Math.min(1.6f, dp * 0.65f));
            double cx = lonToTileX(centerLng, zoom);
            double cy = latToTileY(centerLat, zoom);

            int startX = (int) Math.floor(cx - (w / 2.0) / tileSizePx);
            int endX = (int) Math.floor(cx + (w / 2.0) / tileSizePx);
            int startY = (int) Math.floor(cy - (h / 2.0) / tileSizePx);
            int endY = (int) Math.floor(cy + (h / 2.0) / tileSizePx);

            int maxT = 1 << zoom;
            for (int tx = startX; tx <= endX; tx++) {
                for (int ty = startY; ty <= endY; ty++) {
                    float px = (float) (w / 2.0 + (tx - cx) * tileSizePx);
                    float py = (float) (h / 2.0 + (ty - cy) * tileSizePx);
                    dstRect.set(px, py, px + tileSizePx, py + tileSizePx);

                    Bitmap bmp = getOrLoadTile(tx, ty, zoom, layer);
                    if (bmp != null && !bmp.isRecycled()) {
                        canvas.drawBitmap(bmp, null, dstRect, tilePaint);
                    } else {
                        // Draw parent tile sub-quadrant if cached so zooming never flashes empty space!
                        boolean drewParent = false;
                        if (zoom > 2 && ty >= 0 && ty < maxT) {
                            int normTx = ((tx % maxT) + maxT) % maxT;
                            int pZ = zoom - 1;
                            int pX = normTx >> 1;
                            int pY = ty >> 1;
                            Bitmap parentBmp = TILE_MEM_CACHE.get(layer + "_" + pZ + "_" + pX + "_" + pY);
                            if (parentBmp != null && !parentBmp.isRecycled()) {
                                int pw = parentBmp.getWidth();
                                int ph = parentBmp.getHeight();
                                int subX = (normTx & 1) * (pw / 2);
                                int subY = (ty & 1) * (ph / 2);
                                srcRect.set(subX, subY, subX + pw / 2, subY + ph / 2);
                                canvas.drawBitmap(parentBmp, srcRect, dstRect, tilePaint);
                                drewParent = true;
                            }
                        }
                        if (!drewParent) {
                            canvas.drawRect(dstRect, gridPaint);
                        }
                    }
                }
            }

            // Center Target Pin + Glowing Cyan Pulse Ring
            float mx = w / 2f;
            float my = h / 2f;
            float ringR = 17f * dp;
            canvas.drawCircle(mx, my, ringR, pinRingFillPaint);
            canvas.drawCircle(mx, my, ringR, pinRingStrokePaint);

            float pinHeadY = my - 21f * dp;
            float pinHeadR = 9.5f * dp;
            pinPath.reset();
            pinPath.moveTo(mx, my);
            pinPath.lineTo(mx - 8.2f * dp, my - 17f * dp);
            pinPath.addCircle(mx, pinHeadY, pinHeadR, Path.Direction.CW);
            pinPath.lineTo(mx + 8.2f * dp, my - 17f * dp);
            pinPath.close();
            canvas.drawPath(pinPath, pinBodyPaint);
            canvas.drawCircle(mx, pinHeadY, pinHeadR, pinBorderPaint);

            pinBorderPaint.setStyle(Paint.Style.FILL);
            canvas.drawCircle(mx, pinHeadY, 3.6f * dp, pinBorderPaint);
            pinBorderPaint.setStyle(Paint.Style.STROKE);

            // Top-Left Layer Badge
            String badgeTxt = "hybrid".equals(layer)
                    ? tr("🛰️ Satellite Hybrid", "🛰️ স্যাটেলাইট হাইব্রিড", "🛰️ सैटेलाइट हाइब्रिड")
                    : ("sat".equals(layer)
                            ? tr("🌍 Pure Satellite", "🌍 স্যাটেলাইট", "🌍 सैटेलाइट")
                            : tr("🗺️ Street Map", "🗺️ নরমাল ম্যাপ", "🗺️ नॉर्मल मैप"));
            float badgePadH = 8f * dp;
            float badgeW = badgeTextPaint.measureText(badgeTxt) + badgePadH * 2f;
            float badgeH = 22f * dp;
            badgeRect.set(8f * dp, 8f * dp, 8f * dp + badgeW, 8f * dp + badgeH);
            canvas.drawRoundRect(badgeRect, 6f * dp, 6f * dp, badgeBgPaint);
            canvas.drawRoundRect(badgeRect, 6f * dp, 6f * dp, badgeBorderPaint);
            Paint.FontMetrics bfm = badgeTextPaint.getFontMetrics();
            float badgeTextY = badgeRect.centerY() - (bfm.ascent + bfm.descent) / 2f;
            canvas.drawText(badgeTxt, badgeRect.left + badgePadH, badgeTextY, badgeTextPaint);

            // Bottom-Right Zoom + / − Buttons
            float btnSize = 34f * dp;
            float marginR = 10f * dp;
            float marginB = 12f * dp;
            float gap = 6f * dp;
            zoomMinusRect.set(w - marginR - btnSize, h - marginB - btnSize, w - marginR, h - marginB);
            zoomPlusRect.set(w - marginR - btnSize, zoomMinusRect.top - gap - btnSize, w - marginR, zoomMinusRect.top - gap);

            canvas.drawRoundRect(zoomPlusRect, 8f * dp, 8f * dp, zoomBtnBgPaint);
            canvas.drawRoundRect(zoomPlusRect, 8f * dp, 8f * dp, zoomBtnBorderPaint);
            Paint.FontMetrics zfm = zoomBtnTextPaint.getFontMetrics();
            float plusY = zoomPlusRect.centerY() - (zfm.ascent + zfm.descent) / 2f;
            canvas.drawText("+", zoomPlusRect.centerX(), plusY, zoomBtnTextPaint);

            canvas.drawRoundRect(zoomMinusRect, 8f * dp, 8f * dp, zoomBtnBgPaint);
            canvas.drawRoundRect(zoomMinusRect, 8f * dp, 8f * dp, zoomBtnBorderPaint);
            float minusY = zoomMinusRect.centerY() - (zfm.ascent + zfm.descent) / 2f;
            canvas.drawText("−", zoomMinusRect.centerX(), minusY, zoomBtnTextPaint);
        }

        private void notifyLocationChanged(boolean isFinal) {
            if (locationListener != null) {
                locationListener.onLocationChanged(centerLat, centerLng, isFinal);
            }
        }

        @Override
        public boolean onTouchEvent(MotionEvent event) {
            ViewParent vp = getParent();
            if (vp != null) {
                vp.requestDisallowInterceptTouchEvent(true);
            }
            int action = event.getActionMasked();
            float tileSizePx = 256f * Math.max(1f, Math.min(1.6f, dp * 0.65f));

            if (action == MotionEvent.ACTION_DOWN) {
                if (tapStartListener != null) {
                    tapStartListener.run();
                }
                downTouchX = event.getX();
                downTouchY = event.getY();
                lastTouchX = downTouchX;
                lastTouchY = downTouchY;
                isDragging = true;
                movedDuringTouch = false;
                pinchStartDist = 0f;
                return true;
            } else if (action == MotionEvent.ACTION_POINTER_DOWN) {
                if (event.getPointerCount() >= 2) {
                    isDragging = false;
                    movedDuringTouch = true;
                    pinchStartDist = (float) Math.hypot(
                            event.getX(0) - event.getX(1),
                            event.getY(0) - event.getY(1)
                    );
                }
                return true;
            } else if (action == MotionEvent.ACTION_MOVE) {
                if (event.getPointerCount() >= 2 && pinchStartDist > 10f) {
                    float newDist = (float) Math.hypot(
                            event.getX(0) - event.getX(1),
                            event.getY(0) - event.getY(1)
                    );
                    if (newDist > pinchStartDist * 1.25f) {
                        changeZoom(1);
                        pinchStartDist = newDist;
                    } else if (newDist < pinchStartDist * 0.78f) {
                        changeZoom(-1);
                        pinchStartDist = newDist;
                    }
                    return true;
                }
                if (isDragging && event.getPointerCount() == 1) {
                    float x = event.getX();
                    float y = event.getY();
                    float dx = x - lastTouchX;
                    float dy = y - lastTouchY;
                    if (Math.hypot(x - downTouchX, y - downTouchY) > 6f * dp) {
                        movedDuringTouch = true;
                    }
                    if (Math.abs(dx) > 0.5f || Math.abs(dy) > 0.5f) {
                        lastTouchX = x;
                        lastTouchY = y;
                        double cx = lonToTileX(centerLng, zoom) - (dx / tileSizePx);
                        double cy = latToTileY(centerLat, zoom) - (dy / tileSizePx);
                        centerLng = tileXToLon(cx, zoom);
                        while (centerLng < -180.0) centerLng += 360.0;
                        while (centerLng > 180.0) centerLng -= 360.0;
                        centerLat = Math.max(-85.0, Math.min(85.0, tileYToLat(cy, zoom)));
                        invalidate();
                        notifyLocationChanged(false);
                    }
                }
                return true;
            } else if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                float upX = event.getX();
                float upY = event.getY();
                if (!movedDuringTouch && action == MotionEvent.ACTION_UP) {
                    if (zoomPlusRect.contains(upX, upY)) {
                        changeZoom(1);
                        isDragging = false;
                        return true;
                    }
                    if (zoomMinusRect.contains(upX, upY)) {
                        changeZoom(-1);
                        isDragging = false;
                        return true;
                    }
                    long nowMs = SystemClock.elapsedRealtime();
                    if (nowMs - lastTapUpMs < 280L) {
                        changeZoom(1);
                        lastTapUpMs = 0L;
                    } else {
                        lastTapUpMs = nowMs;
                        float dx = upX - (getWidth() / 2f);
                        float dy = upY - (getHeight() / 2f);
                        if (Math.hypot(dx, dy) > 3f * dp) {
                            double cx = lonToTileX(centerLng, zoom) + (dx / tileSizePx);
                            double cy = latToTileY(centerLat, zoom) + (dy / tileSizePx);
                            centerLng = tileXToLon(cx, zoom);
                            while (centerLng < -180.0) centerLng += 360.0;
                            while (centerLng > 180.0) centerLng -= 360.0;
                            centerLat = Math.max(-85.0, Math.min(85.0, tileYToLat(cy, zoom)));
                            invalidate();
                        }
                    }
                }
                isDragging = false;
                notifyLocationChanged(true);
                return true;
            }
            return super.onTouchEvent(event);
        }
    }

    // ==================== DEDICATED YOUTUBE SYSTEM HOOKS & ZERO-AD ENGINE ====================

    private static final AtomicBoolean sYouTubeEarlyHooksInstalled = new AtomicBoolean(false);
    private static final AtomicBoolean sYouTubeContextHooksInstalled = new AtomicBoolean(false);
    private static volatile URLStreamHandlerFactory sYtUrlFactoryInstance = null;
    private static final ConcurrentHashMap<Integer, String> YT_RES_ENTRY_NAME_CACHE = new ConcurrentHashMap<Integer, String>();
    private static final Map<View, Integer> HIDDEN_YT_AD_HEIGHTS =
            Collections.synchronizedMap(new WeakHashMap<View, Integer>());
    private static final Map<View, Integer> HIDDEN_YT_AD_VISIBILITY =
            Collections.synchronizedMap(new WeakHashMap<View, Integer>());
    private static volatile boolean sYouTubeAudioMutedForAd = false;
    private static volatile int sYouTubeSavedMusicVolume = -1;
    private static volatile long sYouTubeLastAdAudioSeenMs = 0L;
    private static volatile long sYouTubeLastSkipClickMs = 0L;
    private static volatile String sCachedOriginalCertSha1 = null;

    private static String getOriginalCertSha1Uppercase(Context ctx) {
        if (sCachedOriginalCertSha1 != null) return sCachedOriginalCertSha1;
        String hex = sOriginalSignatureHex;
        if (hex != null && !hex.isEmpty()) {
            try {
                int len = hex.length();
                byte[] sigBytes = new byte[len / 2];
                for (int i = 0; i < sigBytes.length; i++) {
                    int hi = Character.digit(hex.charAt(i * 2), 16);
                    int lo = Character.digit(hex.charAt(i * 2 + 1), 16);
                    sigBytes[i] = (byte) ((hi << 4) | lo);
                }
                MessageDigest md = MessageDigest.getInstance("SHA-1");
                byte[] digest = md.digest(sigBytes);
                StringBuilder sb = new StringBuilder(digest.length * 2);
                for (int i = 0; i < digest.length; i++) {
                    int b = digest[i] & 0xFF;
                    if (b < 16) sb.append('0');
                    sb.append(Integer.toHexString(b).toUpperCase(Locale.US));
                }
                sCachedOriginalCertSha1 = sb.toString();
                return sCachedOriginalCertSha1;
            } catch (Throwable ignored) {}
        }
        return "";
    }

    private static boolean isYouTubeAdUrl(String urlStr) {
        if (urlStr == null || urlStr.isEmpty()) return false;
        String lower = urlStr.toLowerCase(Locale.US);
        // Never block YouTube player ad-break blocking check only AFTER checking ad_break path
        if (lower.contains("/youtubei/v1/player/ad_break") ||
                lower.contains("/get_midroll_info") ||
                lower.contains("/api/stats/ads") ||
                lower.contains("/pagead/") ||
                lower.contains("/ptracking") ||
                lower.contains("/pcs/activeview") ||
                lower.contains("ad_tag=")) {
            return true;
        }
        String host = "";
        try {
            int schemeIdx = lower.indexOf("://");
            if (schemeIdx >= 0) {
                int start = schemeIdx + 3;
                int end = lower.length();
                int slash = lower.indexOf('/', start);
                int q = lower.indexOf('?', start);
                int colon = lower.indexOf(':', start);
                if (slash >= 0 && slash < end) end = slash;
                if (q >= 0 && q < end) end = q;
                if (colon >= 0 && colon < end) end = colon;
                if (end > start) {
                    host = lower.substring(start, end);
                }
            }
        } catch (Throwable ignored) {}

        if (host.isEmpty()) return false;
        // Strict allowlist: never block actual video streams, thumbnails, avatars, or core YouTube APIs
        if (host.equals("googlevideo.com") || host.endsWith(".googlevideo.com") ||
                host.equals("ytimg.com") || host.endsWith(".ytimg.com") ||
                host.equals("ggpht.com") || host.endsWith(".ggpht.com") ||
                host.equals("googleusercontent.com") || host.endsWith(".googleusercontent.com")) {
            return false;
        }
        if (host.equals("doubleclick.net") || host.endsWith(".doubleclick.net") ||
                host.equals("googlesyndication.com") || host.endsWith(".googlesyndication.com") ||
                host.equals("googleadservices.com") || host.endsWith(".googleadservices.com") ||
                host.startsWith("adservice.google.") ||
                host.equals("2mdn.net") || host.endsWith(".2mdn.net") ||
                host.equals("ads.youtube.com") || host.equals("ad.youtube.com") ||
                host.endsWith(".ads.youtube.com")) {
            return true;
        }
        return false;
    }

